UPDATE public.people SET summary = 'Alauddin Humayun Shah Bahmani was the sultan of the Bahmani Sultanate, who reigned between 1458 and 1461. Also known as Humayun Shah Zalim (lit. ''Humayun Shah the cruel''), he is described as a cruel ruler, known for executing people in torturous ways.' WHERE id = 'humayun-shah-zalim-bahmani-1458-bahmani';
UPDATE public.people SET summary = 'Husain, born Ḥusaīn Shāh Chak was the second Chak Sultan who ruled over the Kashmir sultanate. He succeeded his brother Ghazi Shah Chak after Ghazi abdicated the throne in Husain''s favour in 1563. Husain was the 20th Sultan of Kashmir and ruled Kashmir until 1570.' WHERE id = 'husain-shah-1563-kashmir-sultanate';
UPDATE public.people SET summary = 'Hussain Nizam Shah I was the Sultan of Ahmadnagar from 9 February 1554 until his death in 1565. He ascended the throne at age thirteen after his father''s death in 1554, upon which his five brothers fled the kingdom.In 1555 he faced the uprising of Raja Bahirji, the governor of the forts of Galna and Baglana alongwith Dannaya Rai, the governor of Antur Fort.' WHERE id = 'hussain-nizam-shah-i-1553-ahmadnagar';
UPDATE public.people SET summary = 'Hussain Nizam Shah I was the Sultan of Ahmadnagar from 9 February 1554 until his death in 1565. He ascended the throne at age thirteen after his father''s death in 1554, upon which his five brothers fled the kingdom.In 1555 he faced the uprising of Raja Bahirji, the governor of the forts of Galna and Baglana alongwith Dannaya Rai, the governor of Antur Fort.' WHERE id = 'hussain-nizam-shah-ii-1588-ahmadnagar';
UPDATE public.people SET summary = 'Ibrahim Shah Suri was Sultan of Hindustan from January 1555 until his deposition and defeat in February. He came to power after revolting against Adil Shah and defeating him, but was himself defeated by Sikandar Shah Suri who succeeded him shortly after.' WHERE id = 'ibrahim-shah-suri-1555-sur';
UPDATE public.people SET summary = 'Indra Pala (ruled 960–990) was ruler of Pala Dynasty (900–1100) of Kamarupa Kingdom.' WHERE id = 'indra-pala-960-kamarupa';
UPDATE public.people SET summary = 'Islam Shah Suri (born Jalal Khan; 1507 – 22 November 1554) also known as Salim Shah Suri, was Sultan of Hindustan from 27 May 1545 until his death in 1554. He was the second ruler of the Sur Empire which ruled parts of India in the mid-16th century. He was the second son of Sher Shah Suri.' WHERE id = 'islam-shah-suri-1545-sur';
UPDATE public.people SET summary = 'Jaitugi (1165–1200), also known as Jaitrapala, was a ruler of the Seuna (Yadava) dynasty from 1191 to 1200.' WHERE id = 'jaitugi-i-1191-yadava';
