UPDATE public.people SET summary = 'Jalaluddin Fateh Shah was the last ruler of later Ilyas Shahi dynasty of the Bengal Sultanate reigning from 1481 to 1487. He was the uncle and successor of Sultan Shamsuddin Yusuf Shah.' WHERE id = 'jalaluddin-fateh-shah-1481-bengal-sultanate';
UPDATE public.people SET summary = 'Jalaluddin Muhammad Shah born as Jadu was a 15th-century Sultan of Bengal and an important figure in medieval Bengali history. Born a Hindu to his aristocratic father Raja Ganesha, the patriarch of the Ganesha dynasty, he assumed the throne of Bengal after a coup which overthrew the Ilyas Shahi dynasty. He converted to Islam and ruled the Bengal Sultanate for 16 years.' WHERE id = 'jalaluddin-muhammad-shah-1415-bengal-sultanate';
UPDATE public.people SET summary = 'Jam Ali Sher was the eighth Sultan of Sindh. He belonged to the Samma dynasty, which ruled from 1351 to 1520.' WHERE id = 'jam-ali-sher-1406-samma';
