UPDATE public.people SET summary = 'Ruknuddin Shah better known as Jam Tamachi was the third and fifth Sultan of Sindh by succession, belonging to the Samma dynasty reigning first as a Diarch to Jam Togachi from 1368 to 1371 and then as a sole independent Monarch from 1389 to 1392.' WHERE id = 'jam-tamachi-1367-samma';
UPDATE public.people SET summary = 'Khairuddin Shah better known as Jam Togachi was the third Sultan of Sindh. He belonged to the Samma dynasty, reigning as a diarch to Jam Tamachi from 1368 to 1370.' WHERE id = 'jam-togachi-1368-samma';
