UPDATE public.people SET summary = 'Sultan-ush-Sharq Atabak-i-Azam Malik Sarwar (died 1399) was the first Sultan of Jaunpur from 1394 to 1399 and the founder of the Sharqi dynasty.' WHERE id = 'malik-sarwar-1394-jaunpur';
UPDATE public.people SET summary = 'Mallu Adil Shah, of the Adil Shahi dynasty, was the Sultan of the Bijapur Sultanate of modern-day southern India. He ruled for a short period in 1534, before being deposed and blinded.' WHERE id = 'mallu-adil-shah-1534-bijapur';
UPDATE public.people SET summary = 'Moggallana III was a King of the Anuradhapura Kingdom (present-day Sri Lanka) who reigned from 614 AD to 619 AD. He is primarily remembered in the chronicles for his violent rise to power and his eventual overthrow by his sword-bearer, Silameghavanna.' WHERE id = 'moggallana-iii-608-anuradhapura';
UPDATE public.people SET summary = 'Muizuddin Muhammad Mubarak Shah II was the Sultan of Delhi from 1421 to 1434 and the second monarch of the Sayyid dynasty which ruled the Delhi Sultanate. He was the son of Khizr Khan.' WHERE id = 'mubarak-shah-1421-delhi-sultanate';
UPDATE public.people SET summary = 'Muhammad Adil Shah (Muhammad Mubariz Khan; died 1557) was Sultan of the Sur Empire from December 1554 until his defeat in January 1555. He was the last Suri ruler of the united empire, after which the empire fell into civil war.' WHERE id = 'muhammad-adil-shah-1554-sur';
UPDATE public.people SET summary = 'Fakhr-ud-Din Muhammad Shah, better known as Muhammad bin Tughluq, or Muhammad II, also known by his epithets, The Eccentric Prince, and The Mad Sultan, was the eighteenth Sultan of Delhi. He reigned from February 1325 until his death in March 1351. Muhammad was the eldest son of Ghiyath al-Din Tughluq, founder of the Tughlaq dynasty.' WHERE id = 'muhammad-bin-tughluq-1325-delhi-sultanate';
UPDATE public.people SET summary = 'Muhammad of Ghazni was Sultan of the Ghaznavid Empire briefly in 1030, and then later from 1040 to 1041. He ascended the throne upon the death of his father Mahmud in 1030. He was the younger of a set of twins; this circumstance resulted in civil strife. His reign lasted five months before he was overthrown by his twin Ma''sud I, after which he was blinded and imprisoned on the order of Ma''sud I.' WHERE id = 'muhammad-of-ghazni-1030-ghaznavid';
UPDATE public.people SET summary = 'Mujahid Shah Bahmani was the third ruler of the Bahmani Sultanate. He was the son of Mohammed Shah I. Unlike his predecessors, Mujahid only had a reign of three years because he was assassinated by his cousin, Daud Shah Bahmani.' WHERE id = 'mujahid-shah-1375-bahmani';
UPDATE public.people SET summary = 'Mularaja (r. 941–996) was the king of Gujarat from 941 to 996 and the founder of the Chaulukya dynasty. Also known as the Chaulukyas of Gujarat or Solanki, this dynasty ruled parts of present-day Gujarat. Mularaja supplanted the last Chavda king, and founded an independent kingdom with his capital in Anahilapataka in 940–941.' WHERE id = 'mularaja-940-chaulukya';
UPDATE public.people SET summary = 'Mularaja (r. 1175 – 1178 CE), also known as Bala Mularaja (lit. ''Child Mularaja''), was an Indian king from the Chaulukya dynasty of Gujarat. He ruled the present-day Gujarat and surrounding areas from his capital Anahilapataka (modern Patan). He ascended the throne as a child, and his mother Naiki Devi acted as the regent during his short reign. The Chaulukyas repulsed a Ghurid invasion when he was 13 years old.' WHERE id = 'mularaja-ii-1175-chaulukya';
UPDATE public.people SET summary = 'Murtaza Nizam Shah III, was a Nizam Shahi boy prince who in the year 1633 became the nominal Sultan of Ahmednagar. He was subjected to the authority of the Mughal Emperor Shah Jahan.' WHERE id = 'murtaza-nizam-shah-i-1565-ahmadnagar';
UPDATE public.people SET summary = 'Murtaza Nizam Shah III, was a Nizam Shahi boy prince who in the year 1633 became the nominal Sultan of Ahmednagar. He was subjected to the authority of the Mughal Emperor Shah Jahan.' WHERE id = 'murtaza-nizam-shah-iii-1633-ahmadnagar';
UPDATE public.people SET summary = 'Nandivarman II (718–796) was a Pallava monarch who reigned in southern India. Sen states Nandivarman reigned from 731 to 796 and built the Vaikuntha-Perumal Temple. From the Kasakkudi plates, it is learnt that Nandivarman II was a descendent of Bhimavarman, the younger brother of Pallava king Simhavishnu.' WHERE id = 'nandivarman-ii-732-pallava';
UPDATE public.people SET summary = 'Naravarman (reigned c. 1094–1133), also known as Naravarma-deva, was an Indian king from the Paramara dynasty, who ruled in the Malwa region of central India. The Paramara power greatly declined during his reign, as a result of multiple military defeats.' WHERE id = 'naravarman-1094-paramara';
UPDATE public.people SET summary = 'Nāṣir ad-Dīn Naṣrat Shāh (r. 1519–1533), also known as Nusrat Shah, was the second Sultan of Bengal belonging to the Hussain Shahi dynasty. He continued with his father''s expansionist policies but by 1526, had to contend with the Mughal ascendency in the Battle of Ghaghra. Simultaneously, Nasrat Shah launched an invasion of the Ahom kingdom.' WHERE id = 'nasiruddin-nasrat-shah-1518-bengal-sultanate';
