UPDATE public.people SET summary = 'Paramesvaravarman II was a Pallava Monarch who reigned from 725 to 731. He was slain in battle by the Gangas leaving no heirs to the Pallava throne.' WHERE id = 'paramesvaravarman-ii-725-pallava';
