UPDATE public.people SET summary = 'Shahi Tegin, Tegin Shah or Sri Shahi was a king of the Turk Shahis, a dynasty of Western Turk or mixed Western Turk-Hephthalite origin who ruled from Kabul and Kapisa to Gandhara in the 7th to 9th centuries.' WHERE id = 'tegin-shah-680-turk-shahis';
UPDATE public.people SET summary = 'Tirumala Nayaka (died 16 February 1659) was the ruler of Madurai Nayak Dynasty from 1623 until his death in 1659. His contributions are found in the many splendid buildings and temples of Madurai. He belongs to Nayak caste. His kingdom was under constant threat from the armies of Bijapur Sultanate and the other neighbouring Muslim kingdoms, which he managed to repulse successfully.' WHERE id = 'tirumala-nayak-1623-madurai-nayaks';
UPDATE public.people SET summary = 'Traillokyachandra (reigned c. 900 – 930) was the first ruler of the Chandra dynasty in eastern Bengal. His father, Subarnachandra, was a vassal to the earlier rulers of the Harikela. Traillokyachandra established the dynasty, centered at Devaparvata (near Mainamati, Comilla) and expanded into modern Barisal division before declaring himself as Maharajadhiraja.' WHERE id = 'traillokyachandra-900-chandra';
UPDATE public.people SET summary = 'Tribhuvanapala (r. c. 1240–1244 CE) was the last king of the Chaulukya dynasty of western India. He ruled parts of present-day Gujarat from his capital at Anahilapataka (modern Patan). He ruled for a short period before dying heirless or being dethroned, after which the Vaghela dynasty assumed control of the kingdom.' WHERE id = 'tribhuvanapala-1240-chaulukya';
UPDATE public.people SET summary = 'Ghiyath al-Din Tughluq Shah II, born Tughluq Khan, was a Sultan of the Tughlaq dynasty of the Delhi Sultanate. He succeeded his great-grandfather, Firoz Shah Tughlaq. Tughluq Shah II was the son of Fateh Khan and the grandson of Firuz Khan, oldest son and heir apparent of sultan Firoz Shah Tughlaq.' WHERE id = 'tughluq-khan-1388-delhi-sultanate';
UPDATE public.people SET summary = 'Uchchala (1070 – 8 December 1111), also known as Uchchala Deva, was the King of Kashmir from 1101 to 1111. He belonged to the Utpala dynasty, a Hindu Kingdom of Kashmiri rulers and was the founder of the Second Lohara dynasty. He was the close relative of Harsha and the brother of Sussala.' WHERE id = 'uchchala-1101-lohara';
