UPDATE public.people SET summary = 'Vira-Varman (IAST: Vīravarman, reigned c. 1245-1285 CE) was a king of the Chandela dynasty of central India. He ruled the Jejakabhukti region (Bundelkhand in present-day Madhya Pradesh and Uttar Pradesh).' WHERE id = 'vira-varman-ii-1311-chandela';
UPDATE public.people SET summary = 'Vishvarupa Sena ,, also known as Biswaroop Sen in vernacular literature, was the fifth ruler from the Sena dynasty of the Bengal region on the Indian subcontinent.' WHERE id = 'vishvarupa-sena-1206-sena';
UPDATE public.people SET summary = 'Viswanatha Nayaka (died 1564) was the Vijayanagara viceroy to Madurai in south India and later the ruler of Madurai from 1529 to 1564. He is the founder of the Nayak dynasty of Madurai. He hailed from the Garikepati family of Balija caste.' WHERE id = 'viswanatha-nayak-1529-madurai-nayaks';
UPDATE public.people SET summary = 'Yashovarman (IAST: Yaśovarman; reigned 1133–1142) was an Indian king from the Paramara dynasty, who ruled in the Malwa region of central India. He was defeated and imprisoned by the Chaulukya king Jayasimha Siddharaja, and appears to have ruled as a Chaulukya subordinate after 1133.' WHERE id = 'yashovarman-1133-paramara';
UPDATE public.people SET summary = 'Nasir al-Din Muhammad Yusuf Shah, better known as Yousuf Shah Chak was the fourth Sultan of Kashmir from the Chak dynasty from 1578 to 1579 and then from 1580 to 1586. Yousuf succeeded his father, Ali Shah Chak, who crowned Yousuf before he died. Yousuf defeated all other contenders for the throne, including his uncle Abdal Chak, and ascended the throne in 1578.' WHERE id = 'yousuf-shah-1578-kashmir-sultanate';
UPDATE public.people SET summary = 'Qutb al-Din Zayn al-Abidin, more famously known as Zayn al-Abidin the Great, was the ninth sultan of the Kashmir Sultanate. He was given the mandate to rule in 1418 in the absence of his brother, Ali Shah before defeating him in the ensuing civil war in 1420 with the help of Jasrat Khokhar. After his illness and subsequent death, his son Haider Shah succeeded him in 1470. He is remembered as Buḍshāh (lit.' WHERE id = 'zayn-al-abidin-1418-kashmir-sultanate';
