INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('aggabodhi-i-571-anuradhapura', 'aggabodhi-i-571-anuradhapura', 'Aggabodhi I', 'King of Anuradhapura', 'anuradhapura', 'life'::public.person_date_type, 'Aggabodhi I (also known as Akbo) was a king of the Anuradhapura Kingdom in the 6th and 7th centuries. His reign, lasting 34 years (571–604 AD), is remembered as a period of significant prosperity, peace, and major advancements in hydraulic engineering and literature.', 571, 604, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-aggabodhi-i-571-anuradhapura', 'Wikipedia: Aggabodhi I', 'digital', 'English Wikipedia, "Aggabodhi I", en.wikipedia.org/wiki/Aggabodhi_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Aggabodhi_I', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-aggabodhi-i-571-anuradhapura', 'Name, dates and summary.', 'aggabodhi-i-571-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('dathappabhuti-531-anuradhapura', 'dathappabhuti-531-anuradhapura', 'Dathappabhuti', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Dathappabhuti (reigned c. 531 CE) was a monarch of the Anuradhapura Kingdom of Sri Lanka. He was the second son of King Silakala. His reign was short-lived, lasting only six months, and was characterized by a violent war of succession known as the "War of the Three Brothers."', 531, 540, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-dathappabhuti-531-anuradhapura', 'Wikipedia: Dathappabhuti', 'digital', 'English Wikipedia, "Dathappabhuti", en.wikipedia.org/wiki/Dathappabhuti (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Dathappabhuti', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-dathappabhuti-531-anuradhapura', 'Name, dates and summary.', 'dathappabhuti-531-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('dhatusena-455-anuradhapura', 'dhatusena-455-anuradhapura', 'Dhatusena', 'King of Sri Lanka (r. 455–473)', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Dhatusena was a king of Sri Lanka who reigned from 455 to 473 AD. He was the first king of the Moriyan dynasty. In some records, he is also identified as Dasenkeli. Dhatusena reunited the country under his rule after twenty-six years of anarchy, defeating the six Dravidians that were ruling the country at that time. Dhatusena built large reservoirs and canals to augment the agriculture in the country.', 455, 473, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-dhatusena-455-anuradhapura', 'Wikipedia: Dhatusena', 'digital', 'English Wikipedia, "Dhatusena", en.wikipedia.org/wiki/Dhatusena (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Dhatusena', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-dhatusena-455-anuradhapura', 'Name, dates and summary.', 'dhatusena-455-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kashyapa-i-448-anuradhapura', 'kashyapa-i-448-anuradhapura', 'Kashyapa I', 'King of Sri Lanka from 473 to 495', 'anuradhapura', 'life'::public.person_date_type, 'Kashyapa I, also known as Kasyapa I or Kassapa I, was a king of Sri Lanka, who ruled the country from 473 to 495 CE. He was the second king of the royal Moriya dynasty of Sri Lanka. Kashyapa is credited with the construction of the Sigiriya citadel and the surrounding city.', 448, 495, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-kashyapa-i-448-anuradhapura', 'Wikipedia: Kashyapa I', 'digital', 'English Wikipedia, "Kashyapa I", en.wikipedia.org/wiki/Kashyapa_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Kashyapa_I', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-kashyapa-i-448-anuradhapura', 'Name, dates and summary.', 'kashyapa-i-448-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kassapa-vi-1017-anuradhapura', 'kassapa-vi-1017-anuradhapura', 'Kassapa VI', 'King of Anuradhapura-in-exile from 1029 to 1040', 'anuradhapura', 'life'::public.person_date_type, 'Kassapa VI (d. 1040) also known as Vikramabahu before his coronation was King of Anuradhapura-in-exile. Following the death of his father in 1029, Vikramabahu led the resistance movement against the Chola invaders of the country, ruling from the southern principality of Ruhuna from 1029 to 1041.', 1017, 1041, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-kassapa-vi-1017-anuradhapura', 'Wikipedia: Kassapa VI', 'digital', 'English Wikipedia, "Kassapa VI", en.wikipedia.org/wiki/Kassapa_VI (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Kassapa_VI', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-kassapa-vi-1017-anuradhapura', 'Name, dates and summary.', 'kassapa-vi-1017-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kittisena-524-anuradhapura', 'kittisena-524-anuradhapura', 'Kittisena', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Kittisena, was King of Anuradhapura in the 6th century, whose reign lasted the year 524. He succeeded his father Kumara Dhatusena as King of Anuradhapura. He was assassinated and succeeded by his uncle Siva II.', 524, 524, 'about', 'about', 'likely');
