INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kittisiri-meghavanna-551-anuradhapura', 'kittisiri-meghavanna-551-anuradhapura', 'Kittisiri Meghavanna', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Kithsirimegha (reigned 551 – 569 CE) was a monarch of the Anuradhapura Kingdom. He was the son and successor of King Moggallana II and is historically noted as the final ruler of the Dhatusena dynasty. His reign is characterized by administrative decline, political corruption, and a significant scholarly dispute regarding the duration of his rule.', 551, 569, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-kittisiri-meghavanna-551-anuradhapura', 'Wikipedia: Kittisiri Meghavanna', 'digital', 'English Wikipedia, "Kittisiri Meghavanna", en.wikipedia.org/wiki/Kittisiri_Meghavanna (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Kittisiri_Meghavanna', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-kittisiri-meghavanna-551-anuradhapura', 'Name, dates and summary.', 'kittisiri-meghavanna-551-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kumara-dhatusena-515-anuradhapura', 'kumara-dhatusena-515-anuradhapura', 'Kumara Dhatusena', 'Ruler of Anuradhapura Kingdom', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Kumara Dhatusena, was King of Anuradhapura in the 6th century, whose reign lasted from 515 to 524. He succeeded his father Moggallana I as King of Anuradhapura and was succeeded by his son Kittisena.', 515, 524, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-kumara-dhatusena-515-anuradhapura', 'Wikipedia: Kumara Dhatusena', 'digital', 'English Wikipedia, "Kumara Dhatusena", en.wikipedia.org/wiki/Kumara_Dhatusena (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Kumara_Dhatusena', 'CC BY-SA 4.0');
