INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('maha-naga-of-anuradhapura-569-anuradhapura', 'maha-naga-of-anuradhapura-569-anuradhapura', 'Maha Naga of Anuradhapura', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Mahanaga (reigned 569 – 571 CE) was a monarch of the Anuradhapura Kingdom of Sri Lanka. Originally a regional ruler of Ruhuna, he ascended the throne of Anuradhapura after a successful rebellion, thereby ending the Dhatusena dynasty and establishing a new royal lineage. His rise to power is steeped in legend, involving prophecies and a long period of patience before claiming the throne.', 569, 571, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-maha-naga-of-anuradhapura-569-anuradhapura', 'Wikipedia: Maha Naga of Anuradhapura', 'digital', 'English Wikipedia, "Maha Naga of Anuradhapura", en.wikipedia.org/wiki/Maha_Naga_of_Anuradhapura (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Maha_Naga_of_Anuradhapura', 'CC BY-SA 4.0');
