INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('manavanna-of-anuradhapura-684-anuradhapura', 'manavanna-of-anuradhapura-684-anuradhapura', 'Manavanna of Anuradhapura', 'King of Anuradhapura from 684 to 718', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Manavamma, also known as Manavarman in Indian sources, was king of Anuradhapura from 684 AD to 718 AD. Considered an important monarch of the Anuradhapura kingdom, he is known for concluding almost half a century of anarchy and ushering an era of prosperity within the nation.', 684, 718, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-manavanna-of-anuradhapura-684-anuradhapura', 'Wikipedia: Manavanna of Anuradhapura', 'digital', 'English Wikipedia, "Manavanna of Anuradhapura", en.wikipedia.org/wiki/Manavanna_of_Anuradhapura (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Manavanna_of_Anuradhapura', 'CC BY-SA 4.0');
