INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('moggallana-i-497-anuradhapura', 'moggallana-i-497-anuradhapura', 'Moggallana I', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Moggallāna I,was King of Anuradhapura in the 6th century, whose reign lasted from 497 to 515. After defeating his brother Kashyapa I in a civil war, he replaced Kashyapa as King of Anuradhapura, and was succeeded by his son Kumara Dhatusena.', 497, 515, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-moggallana-i-497-anuradhapura', 'Wikipedia: Moggallana I', 'digital', 'English Wikipedia, "Moggallana I", en.wikipedia.org/wiki/Moggallana_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Moggallana_I', 'CC BY-SA 4.0');
