INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('moggallana-ii-531-anuradhapura', 'moggallana-ii-531-anuradhapura', 'Moggallana II', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Moggallana II (reigned 531 – 551 CE) was a monarch of the Anuradhapura Kingdom of Sri Lanka. He was the eldest son of King Silakala and ascended the throne following a civil war against his brother, Dathappabhuti. Second only to King Mahasena and King Dhatusena as a tank builder, Moggallana II is recognized as one of the most distinguished and greatest kings of ancient Ceylon.', 531, 551, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-moggallana-ii-531-anuradhapura', 'Wikipedia: Moggallana II', 'digital', 'English Wikipedia, "Moggallana II", en.wikipedia.org/wiki/Moggallana_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Moggallana_II', 'CC BY-SA 4.0');
