INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('silakala-ambasamanera-518-anuradhapura', 'silakala-ambasamanera-518-anuradhapura', 'Silakala Ambasamanera', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Silakala, (reigned c. 518 – 531 CE) was a monarch of the Anuradhapura Kingdom in Sri Lanka. Initially known as Ambasamanera during his time as a monk in India, he is historically significant for bringing the Hair Relic (Keshadhatu) of the Buddha to Sri Lanka and for his subsequent rise to the throne through military rebellion.', 518, 531, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-silakala-ambasamanera-518-anuradhapura', 'Wikipedia: Silakala Ambasamanera', 'digital', 'English Wikipedia, "Silakala Ambasamanera", en.wikipedia.org/wiki/Silakala_Ambasamanera (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Silakala_Ambasamanera', 'CC BY-SA 4.0');
