INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('siva-ii-524-anuradhapura', 'siva-ii-524-anuradhapura', 'Siva II', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Siva II, was King of Anuradhapura in the 6th century, whose reign lasted from 524 to 525. He succeeded his nephew Kittisena as King of Anuradhapura and was succeeded by Upatissa II.', 524, 525, 'about', 'about', 'likely');
