INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('upatissa-ii-517-anuradhapura', 'upatissa-ii-517-anuradhapura', 'Upatissa II', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Upatissa II, (reigned c. 517 – 518 CE) was a monarch of the Anuradhapura Kingdom of Sri Lanka. He ascended the throne during a period of political instability following the death of King Kumara Dhatusena. His short reign of one and a half years was dominated by the internal power struggle against the nobleman Silakala, which ultimately led to the King''s death and the end of his regime.', 517, 518, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-upatissa-ii-517-anuradhapura', 'Wikipedia: Upatissa II', 'digital', 'English Wikipedia, "Upatissa II", en.wikipedia.org/wiki/Upatissa_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Upatissa_II', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-upatissa-ii-517-anuradhapura', 'Name, dates and summary.', 'upatissa-ii-517-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ahmad-shah-i-wali-1422-bahmani', 'ahmad-shah-i-wali-1422-bahmani', 'Ahmad Shah I Wali', 'Sultan of the Bahmani Sultanate from 1422 to 1436', 'bahmani', 'time_as_ruler'::public.person_date_type, 'Shihab-ud-Din Ahmad Shah I Bahmani, also known as Ahmad Shah Wali (lit. ''saint''), was the Sultan of the Bahmani Sultanate from 1 October 1422 to 17 April 1436, and was a great patron of arts and culture. He brought Persian artisans from Iran, including the metal-worker Abdulla-bin-Kaiser, who was the master of Bidriware, the inlaying of zinc alloy with silver and gold.', 1422, 1436, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-ahmad-shah-i-wali-1422-bahmani', 'Wikipedia: Ahmad Shah I Wali', 'digital', 'English Wikipedia, "Ahmad Shah I Wali", en.wikipedia.org/wiki/Ahmad_Shah_I_Wali (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Ahmad_Shah_I_Wali', 'CC BY-SA 4.0');
