INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ala-ud-din-bahman-shah-1291-bahmani', 'ala-ud-din-bahman-shah-1291-bahmani', 'Ala-ud-Din Bahman Shah', 'Sultan of the Bahmani Sultanate from 1347 to 1358', 'bahmani', 'life'::public.person_date_type, 'Ala-ud-Din Hasan Bahman Shah was the founder and Sultan of the Bahmani Sultanate from 3 August 1347 until his death in 1358.', 1291, 1358, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-ala-ud-din-bahman-shah-1291-bahmani', 'Wikipedia: Ala-ud-Din Bahman Shah', 'digital', 'English Wikipedia, "Ala-ud-Din Bahman Shah", en.wikipedia.org/wiki/Ala-ud-Din_Bahman_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Ala-ud-Din_Bahman_Shah', 'CC BY-SA 4.0');
