INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('muhammad-shah-iii-lashkari-1453-bahmani', 'muhammad-shah-iii-lashkari-1453-bahmani', 'Muhammad Shah III Lashkari', 'Sultan of the Bahmani Sultanate from 1463 to 1482', 'bahmani', 'life'::public.person_date_type, 'Muhammad Shah III Lashkari (1453 – 26 March 1482), also known as Shamsuddin Muhammad Shah III, was the sultan of the Bahmani Sultanate from 1463 to 1482. During his reign, he successfully invaded Orissa, compelling its ruler Purushottam Deva to surrender. He also made his brother Hamvira Deva surrender by besieging Kondavidu fort.', 1453, 1482, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-muhammad-shah-iii-lashkari-1453-bahmani', 'Wikipedia: Muhammad Shah III Lashkari', 'digital', 'English Wikipedia, "Muhammad Shah III Lashkari", en.wikipedia.org/wiki/Muhammad_Shah_III_Lashkari (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Muhammad_Shah_III_Lashkari', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-muhammad-shah-iii-lashkari-1453-bahmani', 'Name, dates and summary.', 'muhammad-shah-iii-lashkari-1453-bahmani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('nizam-ud-din-ahmad-iii-1453-bahmani', 'nizam-ud-din-ahmad-iii-1453-bahmani', 'Nizam-Ud-Din Ahmad III', 'Sultan of the Bahmani Sultanate from 1461 to 1463', 'bahmani', 'life'::public.person_date_type, 'Nizam al-Din Ahmad III (c. 1453 – 30 July 1463), also known as Nizam Ahmed Shah and Nizam Shah Bahmani, was the 12th Sultan of the Bahmani Sultanate from 1461 to 1463. During his reign, the administration of the sultanate was mainly handled by the Persian prime minister Mahmud Gawan.', 1453, 1463, 'about', 'about', 'likely');
