INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('taj-ud-din-firuz-shah-1371-bahmani', 'taj-ud-din-firuz-shah-1371-bahmani', 'Taj ud-Din Firuz Shah', 'Sultan of the Bahmani Sultanate from 1397 to 1422', 'bahmani', 'life'::public.person_date_type, 'Taj ud-Din Firoz Shah (died 1 October 1422), also known as Firoz Shah Bahmani, was the ruler of the Bahmani Sultanate in the Deccan Plateau of India from 16 November 1397 to 22 September 1422. Firuz Shah is considered an important ruler of the Bahamani Sultanate. He expanded his kingdom and even succeeded in conquering the Raichur Doab from Vijaynagara kingdoms.', 1371, 1422, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-taj-ud-din-firuz-shah-1371-bahmani', 'Wikipedia: Taj ud-Din Firuz Shah', 'digital', 'English Wikipedia, "Taj ud-Din Firuz Shah", en.wikipedia.org/wiki/Taj_ud-Din_Firuz_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Taj_ud-Din_Firuz_Shah', 'CC BY-SA 4.0');
