INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ikhtiyaruddin-ghazi-shah-1349-bengal-sultanate', 'ikhtiyaruddin-ghazi-shah-1349-bengal-sultanate', 'Ikhtiyaruddin Ghazi Shah', 'Sultan of Sonargaon from 1349 to 1352', 'bengal-sultanate', 'time_as_ruler'::public.person_date_type, 'Ikhtiyaruddin Ghazi Shah was an independent sultan of Sonargaon.', 1349, 1352, 'about', 'about', 'likely');
