INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ghiyasuddin-bahadur-shah-1344-bengal-sultanate', 'ghiyasuddin-bahadur-shah-1344-bengal-sultanate', 'Ghiyasuddin Bahadur Shah', 'Sultan of Lakhnauti (1322–1324) and Delhi Sultanate''s governor of Bengal (1324–1328)', 'bengal-sultanate', 'time_as_ruler'::public.person_date_type, 'Ghiyasuddin Bahadur Shah I was the son and successor of Sultan Shamsuddin Firoz Shah of the Bengal kingdom of Lakhnauti. He ruled the kingdom as an independent ruler during 1322–1324 CE and as a governor during 1324–1328 CE.', 1344, 1359, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-ghiyasuddin-bahadur-shah-1344-bengal-sultanate', 'Wikipedia: Ghiyasuddin Bahadur Shah', 'digital', 'English Wikipedia, "Ghiyasuddin Bahadur Shah", en.wikipedia.org/wiki/Ghiyasuddin_Bahadur_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Ghiyasuddin_Bahadur_Shah', 'CC BY-SA 4.0');
