INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('fakhruddin-mubarak-shah-1338-bengal-sultanate', 'fakhruddin-mubarak-shah-1338-bengal-sultanate', 'Fakhruddin Mubarak Shah', 'Sultan of Sonargaon from 1338 to 1349', 'bengal-sultanate', 'time_as_ruler'::public.person_date_type, 'Fakhruddin Mubarak Shah, also known simply as Fakhra, was a Bengali Muslim ruler and the founder of an independent sultanate and the Mubarak Shahi Dynasty, covering modern-day eastern and southeastern Bangladesh. Muhammad Abdur Rahim described Fakhruddin as "a great Bengali warrior and military organiser". His kingdom was centred in the city of Sonargaon, which emerged as a major regional power during his reign.', 1338, 1349, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-fakhruddin-mubarak-shah-1338-bengal-sultanate', 'Wikipedia: Fakhruddin Mubarak Shah', 'digital', 'English Wikipedia, "Fakhruddin Mubarak Shah", en.wikipedia.org/wiki/Fakhruddin_Mubarak_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Fakhruddin_Mubarak_Shah', 'CC BY-SA 4.0');
