INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('nuruddin-sikandar-shah-1481-bengal-sultanate', 'nuruddin-sikandar-shah-1481-bengal-sultanate', 'Nuruddin Sikandar Shah', 'Sultan of Bengal in 1481', 'bengal-sultanate', 'time_as_ruler'::public.person_date_type, 'Nuruddin Sikandar Shah was the Sultan of Bengal in 1481 CE for a brief number of days.', 1481, 1481, 'about', 'about', 'likely');
