INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('mohammed-adil-shah-of-bijapur-1601-bijapur', 'mohammed-adil-shah-of-bijapur-1601-bijapur', 'Mohammed Adil Shah of Bijapur', 'Sultan of Bijapur from 1627 to 1656', 'bijapur', 'life'::public.person_date_type, 'Mohammed Adil Shah (1612 – 4 November 1656) was the seventh sultan of Bijapur, ascending the throne in 1627. During his reign, he assisted the Mughals with their campaigns against the Ahmednagar Sultanate and signed a peace treaty with them in 1636. He died in 1656 and was buried in the Gol Gumbaz.', 1601, 1656, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-mohammed-adil-shah-of-bijapur-1601-bijapur', 'Wikipedia: Mohammed Adil Shah of Bijapur', 'digital', 'English Wikipedia, "Mohammed Adil Shah of Bijapur", en.wikipedia.org/wiki/Mohammed_Adil_Shah_of_Bijapur (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Mohammed_Adil_Shah_of_Bijapur', 'CC BY-SA 4.0');
