INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('abhinavaditya-645-chalukya-badami', 'abhinavaditya-645-chalukya-badami', 'Abhinavaditya', 'Chalukya Emperor from 645 to 646', 'chalukya-badami', 'time_as_ruler'::public.person_date_type, 'Abhinavaditya (r. c. 645–646 CE) was a king of the Chalukya dynasty of Vatapi in southern India. He appears to have succeeded his father Adityavarman on the weakened Chalukya throne, in the period following the death of his grandfather Pulakeshin II. He appears to have died heirless, and was probably succeeded by his uncle Chandraditya.', 645, 646, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-abhinavaditya-645-chalukya-badami', 'Wikipedia: Abhinavaditya', 'digital', 'English Wikipedia, "Abhinavaditya", en.wikipedia.org/wiki/Abhinavaditya (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Abhinavaditya', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-abhinavaditya-645-chalukya-badami', 'Name, dates and summary.', 'abhinavaditya-645-chalukya-badami');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('adityavarman-643-chalukya-badami', 'adityavarman-643-chalukya-badami', 'Adityavarman', 'Chalukya Emperor from 643 to 645', 'chalukya-badami', 'time_as_ruler'::public.person_date_type, 'Adityavarma (r. c. 643–645 CE) was a king of the Chalukya dynasty of Vatapi in southern India. He was a son of Pulakeshin II, who was defeated and probably killed when the Pallavas invaded and captured the Chalukya capital Vatapi.', 643, 645, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-adityavarman-643-chalukya-badami', 'Wikipedia: Adityavarman (Chalukya dynasty)', 'digital', 'English Wikipedia, "Adityavarman (Chalukya dynasty)", en.wikipedia.org/wiki/Adityavarman_(Chalukya_dynasty) (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Adityavarman_(Chalukya_dynasty)', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-adityavarman-643-chalukya-badami', 'Name, dates and summary.', 'adityavarman-643-chalukya-badami');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('chandraditya-646-chalukya-badami', 'chandraditya-646-chalukya-badami', 'Chandraditya', 'Chalukya emperor from 646 to 649', 'chalukya-badami', 'time_as_ruler'::public.person_date_type, 'Chandraditya (IAST: Chandrādityā, r. c. 646-649) was a king of the Chalukya dynasty of Vatapi that ruled in the Deccan region of peninsular India. His father Pulakeshin II was a powerful emperor, who was defeated and most probably killed during a Pallava invasion.', 646, 649, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-chandraditya-646-chalukya-badami', 'Wikipedia: Chandraditya (Chalukya dynasty)', 'digital', 'English Wikipedia, "Chandraditya (Chalukya dynasty)", en.wikipedia.org/wiki/Chandraditya_(Chalukya_dynasty) (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Chandraditya_(Chalukya_dynasty)', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-chandraditya-646-chalukya-badami', 'Name, dates and summary.', 'chandraditya-646-chalukya-badami');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kirttivarman-i-566-chalukya-badami', 'kirttivarman-i-566-chalukya-badami', 'Kirttivarman I', 'Chalukya Emperor from 566 to 592', 'chalukya-badami', 'life'::public.person_date_type, 'Kirttivarman I (IAST: Kīrtti-varman; died 592) was the emperor of the Chalukya dynasty from 566 until his death in 592. He ruled parts of present-day Karnataka, Goa, Maharashtra and Andhra Pradesh.', 566, 597, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-kirttivarman-i-566-chalukya-badami', 'Wikipedia: Kirttivarman I', 'digital', 'English Wikipedia, "Kirttivarman I", en.wikipedia.org/wiki/Kirttivarman_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Kirttivarman_I', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-kirttivarman-i-566-chalukya-badami', 'Name, dates and summary.', 'kirttivarman-i-566-chalukya-badami');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('mangalesha-592-chalukya-badami', 'mangalesha-592-chalukya-badami', 'Mangalesha', 'Chalukya Emperor from 592 to 610', 'chalukya-badami', 'time_as_ruler'::public.person_date_type, 'Mangalesha (IAST: Maṅgaleśa, r. c. 592 – c. 610 CE) was a king of the Chalukya dynasty of Vatapi in Karnataka, India. He succeeded his older brother Kirttivarman I on the throne, and ruled a kingdom that stretched from southern Gujarat in north to Bellary-Kurnool region in the south, in the western part of the Deccan region. It included parts of present-day Gujarat, Maharashtra, Goa, Karnataka, and Andhra Pradesh.', 592, 610, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-mangalesha-592-chalukya-badami', 'Wikipedia: Mangalesha', 'digital', 'English Wikipedia, "Mangalesha", en.wikipedia.org/wiki/Mangalesha (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Mangalesha', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-mangalesha-592-chalukya-badami', 'Name, dates and summary.', 'mangalesha-592-chalukya-badami');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('pulakeshin-i-543-chalukya-badami', 'pulakeshin-i-543-chalukya-badami', 'Pulakeshin I', 'Chalukya emperor from 543 to 566', 'chalukya-badami', 'time_as_ruler'::public.person_date_type, 'Pulakeshin (IAST: Pulakeśin, c. 543–566) was the first sovereign ruler of the Chalukya dynasty of Vatapi (modern Badami). He ruled parts of the present-day Maharashtra and Karnataka states in the western Deccan region of India. Pulakeshin established the city of Vatapi, and performed the Ashvamedha sacrifice to assert his sovereign status.', 543, 566, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-pulakeshin-i-543-chalukya-badami', 'Wikipedia: Pulakeshin I', 'digital', 'English Wikipedia, "Pulakeshin I", en.wikipedia.org/wiki/Pulakeshin_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Pulakeshin_I', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-pulakeshin-i-543-chalukya-badami', 'Name, dates and summary.', 'pulakeshin-i-543-chalukya-badami');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('jagadhekamalla-ii-1138-chalukya-kalyani', 'jagadhekamalla-ii-1138-chalukya-kalyani', 'Jagadhekamalla II', 'Western Chalukya Emperor from 1138 to 1151', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Jagadhekamalla II or Jagadhekamalladeva (r. 1138–1151) followed Someshvara III to the Western Chalukya throne. His rule saw the slow decline of the Chalukya empire with the loss of Vengi entirely, though he was still able to control the Hoysalas in the south and the Seuna and Paramara in the north.', 1138, 1151, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-jagadhekamalla-ii-1138-chalukya-kalyani', 'Wikipedia: Jagadhekamalla II', 'digital', 'English Wikipedia, "Jagadhekamalla II", en.wikipedia.org/wiki/Jagadhekamalla_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Jagadhekamalla_II', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-jagadhekamalla-ii-1138-chalukya-kalyani', 'Name, dates and summary.', 'jagadhekamalla-ii-1138-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('jagadhekamalla-iii-1163-chalukya-kalyani', 'jagadhekamalla-iii-1163-chalukya-kalyani', 'Jagadhekamalla III', 'Ruler of Chalukya (Kalyani)', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Jagadhekamalla III (r. 1163–1183 CE) succeeded Tailapa III to the highly diminished Western Chalukya empire. His rule was completely overshowded by the emergence of the Southern Kalachuris under Bijjala II who took control of Basavakalyana and ruled from there. He found refuge in the Banavasi region of the Western Ghats, while Bijjala his former vassal became suzerain at Kalyana in 1162.', 1163, 1183, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-jagadhekamalla-iii-1163-chalukya-kalyani', 'Wikipedia: Jagadhekamalla III', 'digital', 'English Wikipedia, "Jagadhekamalla III", en.wikipedia.org/wiki/Jagadhekamalla_III (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Jagadhekamalla_III', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-jagadhekamalla-iii-1163-chalukya-kalyani', 'Name, dates and summary.', 'jagadhekamalla-iii-1163-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('jayasimha-ii-1015-chalukya-kalyani', 'jayasimha-ii-1015-chalukya-kalyani', 'Jayasimha II', 'Western Chalukya Emperor from 1015 to 1043', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Jayasimha II (r. 1015 – 1043), also known as Jagadhekamalla I and Mallikamoda, succeeded his brother Vikramaditya V on the Western Chalukya throne. He had to fight on many fronts, against the Cholas of Tanjore in the south and the Paramara dynasty in the north, to protect his kingdom. His rule however was an important period of development of Kannada literature.', 1015, 1043, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-jayasimha-ii-1015-chalukya-kalyani', 'Wikipedia: Jayasimha II (Western Chalukya dynasty)', 'digital', 'English Wikipedia, "Jayasimha II (Western Chalukya dynasty)", en.wikipedia.org/wiki/Jayasimha_II_(Western_Chalukya_dynasty) (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Jayasimha_II_(Western_Chalukya_dynasty)', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-jayasimha-ii-1015-chalukya-kalyani', 'Name, dates and summary.', 'jayasimha-ii-1015-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('satyashraya-997-chalukya-kalyani', 'satyashraya-997-chalukya-kalyani', 'Satyashraya', 'Western Chalukya Emperor from 997 to 1008', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Satyashraya (IAST: Satyāśraya; died 1008), also known as Sattiga or Irivabedanga, was a king of the Western Chalukya Empire. During a time of consolidation of the empire in the early 11th century, Satyashraya was involved in several battles with the Chola dynasty of Thanjavur, the Paramara dynasty and Chedi Kingdom of central India, and the Chaulukyas of Gujarat.', 997, 1008, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-satyashraya-997-chalukya-kalyani', 'Wikipedia: Satyashraya', 'digital', 'English Wikipedia, "Satyashraya", en.wikipedia.org/wiki/Satyashraya (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Satyashraya', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-satyashraya-997-chalukya-kalyani', 'Name, dates and summary.', 'satyashraya-997-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('someshvara-i-1042-chalukya-kalyani', 'someshvara-i-1042-chalukya-kalyani', 'Someshvara I', 'Western Chalukya Emperor from 1042 to 1068', 'chalukya-kalyani', 'life'::public.person_date_type, 'Someshvara I (IAST: Someśvara; died 29 March 1068) was a king of the Western Chalukyas. Also known as "Ahavamalla" or "Trilokamalla", Someshvara succeeded his father Jayasimha II to the throne.', 1042, 1068, 'about', 'about', 'likely');
