INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('someshvara-ii-1068-chalukya-kalyani', 'someshvara-ii-1068-chalukya-kalyani', 'Someshvara II', 'Western Chalukya Emperor from 1068 to 1076', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Someshvara II (IAST: Someśvara; r. 1068–1076) was the Western Chalukya king from 1068 to 1076. He was the eldest son of Someshvara I and succeeded him in April 1068. During his reign Someshvara II was constantly under threat from his more ambitious younger brother Vikramaditya VI. Eventually Someshvara was deposed by Vikramaditya VI.', 1068, 1076, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-someshvara-ii-1068-chalukya-kalyani', 'Wikipedia: Someshvara II', 'digital', 'English Wikipedia, "Someshvara II", en.wikipedia.org/wiki/Someshvara_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Someshvara_II', 'CC BY-SA 4.0');
