INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('someshvara-iii-1126-chalukya-kalyani', 'someshvara-iii-1126-chalukya-kalyani', 'Someshvara III', 'King of the Western Chalukya Empire from 1126 to 1138', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Someshvara III (IAST: Someśvara; r. 1126–1138) was a Western Chalukya king (also known as the Kalyani Chalukyas), the son and successor of Vikramaditya VI. He ascended the throne of the Western Chalukya Kingdom in 1126, or 1127.', 1126, 1138, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-someshvara-iii-1126-chalukya-kalyani', 'Wikipedia: Someshvara III', 'digital', 'English Wikipedia, "Someshvara III", en.wikipedia.org/wiki/Someshvara_III (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Someshvara_III', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-someshvara-iii-1126-chalukya-kalyani', 'Name, dates and summary.', 'someshvara-iii-1126-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('someshvara-iv-1181-chalukya-kalyani', 'someshvara-iv-1181-chalukya-kalyani', 'Someshvara IV', 'King of the Western Chalukya empire', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Someshvara IV (IAST: Someśvara; r. 1181–1189) was the last king of the Western Chalukya empire. He made a brief attempt after 1189 to revive the Chalukya kingdom by defeating the waning Kalachuri kingdom. He managed to capture Basavakalyana briefly but failed to prevent the other feudatories, the Seuna, Hoysala and the Kakatiya dynasty from completely overwhelming the Chalukya empire by 1200.', 1181, 1189, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-someshvara-iv-1181-chalukya-kalyani', 'Wikipedia: Someshvara IV', 'digital', 'English Wikipedia, "Someshvara IV", en.wikipedia.org/wiki/Someshvara_IV (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Someshvara_IV', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-someshvara-iv-1181-chalukya-kalyani', 'Name, dates and summary.', 'someshvara-iv-1181-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('tailapa-ii-973-chalukya-kalyani', 'tailapa-ii-973-chalukya-kalyani', 'Tailapa II', 'Ruler of Chalukya (Kalyani)', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Tailapa II (r. c. 973-997) also known as Taila II and by his title Ahavamalla, was the founder of the Western Chalukya Empire in peninsular India. Tailapa claimed descent from the earlier imperial Chalukyas of Vatapi (Badami), and initially ruled as a Rashtrakuta vassal from the Tardavadi-1000 province in the present-day Vijayapura district of Karnataka.', 973, 997, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-tailapa-ii-973-chalukya-kalyani', 'Wikipedia: Tailapa II', 'digital', 'English Wikipedia, "Tailapa II", en.wikipedia.org/wiki/Tailapa_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Tailapa_II', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-tailapa-ii-973-chalukya-kalyani', 'Name, dates and summary.', 'tailapa-ii-973-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('tailapa-iii-1151-chalukya-kalyani', 'tailapa-iii-1151-chalukya-kalyani', 'Tailapa III', 'Western Chalukya Emperor from 1151 to 1162', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Tailapa III (r. 1151–1162) succeeded his brother Jagadhekamalla II to the Western Chalukya throne. His rule saw the beginning of the end of the Chalukya empire. Kakatiya dynasty''s Prola II warred with him, defeated and took the Chalukya king captive. This resulted in other feudatories rising against the Chalukyas. The Seuna and the Hoysala started to take away territory.', 1151, 1162, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-tailapa-iii-1151-chalukya-kalyani', 'Wikipedia: Tailapa III', 'digital', 'English Wikipedia, "Tailapa III", en.wikipedia.org/wiki/Tailapa_III (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Tailapa_III', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-tailapa-iii-1151-chalukya-kalyani', 'Name, dates and summary.', 'tailapa-iii-1151-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('vikramaditya-v-1008-chalukya-kalyani', 'vikramaditya-v-1008-chalukya-kalyani', 'Vikramaditya V', 'Western Chalukya Emperor from 1008 to 1015', 'chalukya-kalyani', 'time_as_ruler'::public.person_date_type, 'Vikaramaditya V (r. 1008–1015) succeeded Satyashraya on the Western Chalukya throne. Vikramaditya was born to Dashavarman (alias Yashovarman), the younger son of the dynasty''s founder Tailapa II, and his wife Bhagyavati. He was Satyashraya''s nephew and had a very uneventful short reign.', 1008, 1015, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-vikramaditya-v-1008-chalukya-kalyani', 'Wikipedia: Vikramaditya V', 'digital', 'English Wikipedia, "Vikramaditya V", en.wikipedia.org/wiki/Vikramaditya_V (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Vikramaditya_V', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-vikramaditya-v-1008-chalukya-kalyani', 'Name, dates and summary.', 'vikramaditya-v-1008-chalukya-kalyani');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('vitukathazhakiya-perumal-1103-chera', 'vitukathazhakiya-perumal-1103-chera', 'Vitukathazhakiya Perumal', 'Satiyaputra Chera ruler of Thagadur', 'chera', 'time_as_ruler'::public.person_date_type, 'Rajarajadevan Vitukathazhakiya Perumal (fl. late 12th century AD), also known as Vyamukta Sravanojjvala in Sanskrit, was an Adigaman Chera ruler of Thagadur (modern Dharmapuri) in northern Tamil Nadu, southern India under Chola monarch Kulothunga III. He was a contemporary of Sengeni Ammaiyappan Hastimalla alias Vikrama Chola Sambuvarayan and Seyyagangar/Siyagangan, both also subordinates of Kulothunga III.', 1103, 1123, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-vitukathazhakiya-perumal-1103-chera', 'Wikipedia: Vitukathazhakiya Perumal', 'digital', 'English Wikipedia, "Vitukathazhakiya Perumal", en.wikipedia.org/wiki/Vitukathazhakiya_Perumal (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Vitukathazhakiya_Perumal', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-vitukathazhakiya-perumal-1103-chera', 'Name, dates and summary.', 'vitukathazhakiya-perumal-1103-chera');
