INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('vijayabahu-iii-1232-dambadeniya', 'vijayabahu-iii-1232-dambadeniya', 'Vijayabahu III', 'King of Dambadeniya', 'dambadeniya', 'time_as_ruler'::public.person_date_type, 'Vijayabahu III was the first King of Dambadeniya, who ruled from 1232- 1236. He was a member of the Sinhala Royal Family who began the Siri Sanga Bo dynasty, he was succeeded by his son Parakkamabahu II. Before he became the king of Dambadeniya, he was a ruler of a small province – a Vanni chieftain.', 1232, 1236, 'about', 'about', 'likely');
