INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('malik-altunia-1202-delhi-sultanate', 'malik-altunia-1202-delhi-sultanate', 'Malik Altunia', 'Ruler of Delhi Sultanate', 'delhi-sultanate', 'life'::public.person_date_type, 'Malik Ikhtiyar-ud-din Altunia was the governor of Bathinda in (Punjab) under the rule of the Delhi Sultanate under the Mamluk dynasty. He was the husband of Razia Sultan.', 1202, 1240, 'about', 'about', 'likely');
