INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('minhaj-i-siraj-juzjani-1193-delhi-sultanate', 'minhaj-i-siraj-juzjani-1193-delhi-sultanate', 'Minhaj-i Siraj Juzjani', 'Ruler of Delhi Sultanate', 'delhi-sultanate', 'life'::public.person_date_type, 'Minhaj-al-Din Abu Amr Othman ibn Siraj-al-Din Muhammad Juzjani (born 1193), simply known as Minhaj al-Siraj Juzjani, was a 13th-century Persian historian born in the region of Ghur.', 1193, 1260, 'about', 'about', 'likely');
