INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('jamal-ud-din-yaqut-1240-delhi-sultanate', 'jamal-ud-din-yaqut-1240-delhi-sultanate', 'Jamal-ud-Din Yaqut', 'Ruler of Delhi Sultanate', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Jamal ud-Din Yaqut (also Yakut; died 1240) was an African Siddi slave-turned-nobleman who was a close confidant of Razia Sultan, the first and only female monarch of the Delhi Sultanate in India. Yakut was the puppet of Razia Sultan''s stepmother, but eventually he became a trustworthy soldier of the Delhi Sultanate.', 1240, 1255, 'about', 'about', 'likely');
