INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('deval-devi-1316-delhi-sultanate', 'deval-devi-1316-delhi-sultanate', 'Deval Devi', 'Ruler of Delhi Sultanate', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Deval Devi (variantly known as Dewal Devi, Dewal Rani, Deval Rani and Dewal Di) was the daughter of Karan Deva II (the last sovereign of the Vaghela dynasty of Gujarat). She was married to Khizr Khan, the eldest son of Alauddin Khalji, in 1308. Eight years later, Khizr Khan was executed by his brother Qutb ud din Mubarak Shah (reigned 1316–1320), and Deval was taken into the latter''s harem.', 1316, 1320, 'about', 'about', 'likely');
