INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('zafar-khan-1299-delhi-sultanate', 'zafar-khan-1299-delhi-sultanate', 'Zafar Khan', 'Ruler of Delhi Sultanate', 'delhi-sultanate', 'life'::public.person_date_type, 'Hizabruddin, better known by his title Zafar Khan, was a general of the Delhi Sultanate ruler Alauddin Khalji. He held charge of Multan, Samana, and Sivistan at various times during Alauddin''s reign.', 1299, 1299, 'about', 'about', 'likely');
