INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('malikzada-firuz-1351-delhi-sultanate', 'malikzada-firuz-1351-delhi-sultanate', 'Malikzada Firuz', 'Wazir of the Delhi Sultanate from 1388 to 1389', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Malikzada Firuz born Firuz Khan was the noble of the Delhi Sultanate during the Tughlaq dynasty. He served as governor of the shiq of Firuzpur under Sultan Firoz Shah Tughluq (r. 1351–1388) and later rose to the position of Wazir under Sultan Tughluq Khan (r. 1388–1389). His son Nasiruddin Mahmud succeeded him in Shiq Firuzpur later founded the independent Kingdom of Kalpi in 1390.', 1351, 1388, 'about', 'about', 'likely');
