INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('malik-maqbul-tilangani-1351-delhi-sultanate', 'malik-maqbul-tilangani-1351-delhi-sultanate', 'Malik Maqbul Tilangani', 'Vizier of Delhi Sultanate (d. 1369)', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Malik Maqbul (Mala Yugandharudu), also referred to as Khan-i-Jahan Maqbul Tilangani and Jahan Khan (d. 1369), was an Indian commander in the Kakatiya Empire who was converted to Islam and rose to become the Wazir of the Delhi Sultanate under Firuz Shah Tughlaq (r. 1351–1388).', 1351, 1388, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-malik-maqbul-tilangani-1351-delhi-sultanate', 'Wikipedia: Malik Maqbul Tilangani', 'digital', 'English Wikipedia, "Malik Maqbul Tilangani", en.wikipedia.org/wiki/Malik_Maqbul_Tilangani (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Malik_Maqbul_Tilangani', 'CC BY-SA 4.0');
