INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('mardan-daulat-1353-delhi-sultanate', 'mardan-daulat-1353-delhi-sultanate', 'Mardan Daulat', 'Ruler of Delhi Sultanate', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Khwaja Dhia ''al-Din, whose complete title was Malik al-Sharq Mardan Daulat Nasir al-Mulk, and better known as Malik Mardan Daulat, was the governor of Multan under the Tughlaq dynasty, succeeding Ayn al-Mulk Mahru in 1362.', 1353, 1368, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-mardan-daulat-1353-delhi-sultanate', 'Wikipedia: Mardan Daulat', 'digital', 'English Wikipedia, "Mardan Daulat", en.wikipedia.org/wiki/Mardan_Daulat (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Mardan_Daulat', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-mardan-daulat-1353-delhi-sultanate', 'Name, dates and summary.', 'mardan-daulat-1353-delhi-sultanate');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('muhammad-sadr-ala-i-1301-delhi-sultanate', 'muhammad-sadr-ala-i-1301-delhi-sultanate', 'Muhammad Sadr Ala-i', 'Ruler of Delhi Sultanate', 'delhi-sultanate', 'life'::public.person_date_type, 'Taj al-Dīn Muhammad Sadr Ala-i bin Ahmad Hasan Dabir-i Abdusi Dehlavi (1301–1351), also known as Ikhtisān-i Dabir, was a 14th-century Muslim author who was born in Delhi, India, at the time of the Delhi Sultanate, where he was a hereditary servant of the Court of the Tughlaq dynasty, and a secretary to the Royal Chancelry. He held the high title of Malik at the Court.', 1301, 1351, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-muhammad-sadr-ala-i-1301-delhi-sultanate', 'Wikipedia: Muhammad Sadr Ala-i', 'digital', 'English Wikipedia, "Muhammad Sadr Ala-i", en.wikipedia.org/wiki/Muhammad_Sadr_Ala-i (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Muhammad_Sadr_Ala-i', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-muhammad-sadr-ala-i-1301-delhi-sultanate', 'Name, dates and summary.', 'muhammad-sadr-ala-i-1301-delhi-sultanate');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('malik-mufarrah-sultani-1382-delhi-sultanate', 'malik-mufarrah-sultani-1382-delhi-sultanate', 'Malik Mufarrah Sultani', 'Delhi Sultanate governor of Gujarat from 1377 to 1391', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Malik Mufarrah Sultani, known by his titles Farhat-ul-Mulk and Rasti Khan, was a Tughlaq-era noble. He the last governor of Gujarat serving ten years from 1382 to 1391. Appointed by Sultan Firuz Shah Tughlaq, he initially consolidated control over the province. After the downfall of Delhi Sultanate''s authority he attempted to assert independence.', 1382, 1391, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-malik-mufarrah-sultani-1382-delhi-sultanate', 'Wikipedia: Malik Mufarrah Sultani', 'digital', 'English Wikipedia, "Malik Mufarrah Sultani", en.wikipedia.org/wiki/Malik_Mufarrah_Sultani (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Malik_Mufarrah_Sultani', 'CC BY-SA 4.0');
