INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('mubarak-shah-ii-1378-delhi-sultanate', 'mubarak-shah-ii-1378-delhi-sultanate', 'Mubarak Shah II', 'Sultan of Delhi from 1421 to 1434', 'delhi-sultanate', 'life'::public.person_date_type, 'Muizuddin Muhammad Mubarak Shah II was the Sultan of Delhi from 1421 to 1434 and the second monarch of the Sayyid dynasty which ruled the Delhi Sultanate. He was the son of Khizr Khan.', 1378, 1434, 'about', 'about', 'likely');
