INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('daulat-khan-lodi-1500-delhi-sultanate', 'daulat-khan-lodi-1500-delhi-sultanate', 'Daulat Khan Lodi', 'Lodi governor of Lahore from 1500 to 1524', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Daulat Khan Lodi was the governor of Lahore during the reign of Sikandar Khan and Ibrahim Lodi, the last rulers of the Lodi dynasty. Due to disaffection with Ibrahim, Daulat invited Babur to invade the empire. He was initially governor of the Jalandhar Doab before being promoted to the governorship of Lahore between 1500 and 1504, and remained so until Babur''s invasion in 1524.', 1500, 1524, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-daulat-khan-lodi-1500-delhi-sultanate', 'Wikipedia: Daulat Khan Lodi', 'digital', 'English Wikipedia, "Daulat Khan Lodi", en.wikipedia.org/wiki/Daulat_Khan_Lodi (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Daulat_Khan_Lodi', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-daulat-khan-lodi-1500-delhi-sultanate', 'Name, dates and summary.', 'daulat-khan-lodi-1500-delhi-sultanate');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ali-of-ghazna-1030-ghaznavid', 'ali-of-ghazna-1030-ghaznavid', 'Ali of Ghazna', 'Ghaznavid sultan from 1048 to 1049', 'ghaznavid', 'time_as_ruler'::public.person_date_type, 'Ali ibn Mas''ud was the Ghaznavid sultan, ruling from 1048 to 1049. The son of Mas''ud I (r. 1030–1040), Ali succeeded his nephew Mas''ud II (r. 1048). Although Abdur Rashid sent an army led by his vizier to Sistan to arrest Ghaznavi, the vizier changed sides and defeated Ali and replaced him with Abd al-Rashid and he was killed in 1050.', 1030, 1040, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-ali-of-ghazna-1030-ghaznavid', 'Wikipedia: Ali of Ghazna', 'digital', 'English Wikipedia, "Ali of Ghazna", en.wikipedia.org/wiki/Ali_of_Ghazna (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Ali_of_Ghazna', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-ali-of-ghazna-1030-ghaznavid', 'Name, dates and summary.', 'ali-of-ghazna-1030-ghaznavid');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('khusrau-shah-of-ghazna-1121-ghaznavid', 'khusrau-shah-of-ghazna-1121-ghaznavid', 'Khusrau Shah of Ghazna', 'Ghaznavid sultan from 1157 to 1160', 'ghaznavid', 'life'::public.person_date_type, 'Khusrau Shah (b. 1121 – d. 1160) was the penultimate sultan of the Ghaznavid Dynasty from 1157 to 1160., and the eldest son of Bahram-Shah. During his short reign, he lost southeastern Afghanistan to Ala al-Din Husayn, Malik of Ghurid empire. He was succeeded by his son, Khusrau Malik.', 1121, 1160, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-khusrau-shah-of-ghazna-1121-ghaznavid', 'Wikipedia: Khusrau Shah of Ghazna', 'digital', 'English Wikipedia, "Khusrau Shah of Ghazna", en.wikipedia.org/wiki/Khusrau_Shah_of_Ghazna (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Khusrau_Shah_of_Ghazna', 'CC BY-SA 4.0');
