INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('mas-ud-iii-of-ghazni-1061-ghaznavid', 'mas-ud-iii-of-ghazni-1061-ghaznavid', 'Mas''ud III of Ghazni', 'Ghaznavid sultan from 1099 to 1115', 'ghaznavid', 'life'::public.person_date_type, 'Mas''ūd III of Ghazna (b. 1061 – d. 1115), was a sultan of the Ghaznavid Empire and son of the Ghaznavid sultan, Ibrahim of Ghazna', 1061, 1115, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-mas-ud-iii-of-ghazni-1061-ghaznavid', 'Wikipedia: Mas''ud III of Ghazni', 'digital', 'English Wikipedia, "Mas''ud III of Ghazni", en.wikipedia.org/wiki/Mas''ud_III_of_Ghazni (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Mas''ud_III_of_Ghazni', 'CC BY-SA 4.0');
