INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('mawdud-of-ghazni-1012-ghaznavid', 'mawdud-of-ghazni-1012-ghaznavid', 'Mawdud of Ghazni', 'Sultan of the Ghaznavid Empire from 1041 to 1050', 'ghaznavid', 'life'::public.person_date_type, 'Shahāb-ud-Dawla Mawdūd, known as Mawdud of Ghazni, was a sultan of the Ghaznavids from 1041 – 1050. He seized the throne of the sultanate from his uncle, Muhammad of Ghazni, in revenge for the murder of his father, Mas''ud I of Ghazni. His brother Majdud in Lahore did not recognize him as sultan, but his sudden death paved the way for Mawdud to exercise control over the eastern portion of the Ghaznavid Empire.', 1012, 1049, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-mawdud-of-ghazni-1012-ghaznavid', 'Wikipedia: Mawdud of Ghazni', 'digital', 'English Wikipedia, "Mawdud of Ghazni", en.wikipedia.org/wiki/Mawdud_of_Ghazni (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Mawdud_of_Ghazni', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-mawdud-of-ghazni-1012-ghaznavid', 'Name, dates and summary.', 'mawdud-of-ghazni-1012-ghaznavid');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('sabuktigin-942-ghaznavid', 'sabuktigin-942-ghaznavid', 'Sabuktigin', 'Ruler of Ghaznavid', 'ghaznavid', 'life'::public.person_date_type, 'Abu Mansur Nasir ad-Din wa''d-Dawla Sabuktigin was the founder of the Ghaznavid dynasty, and amir of Ghazna from 977 to 997. Sabuktigin was a Karluk Turkic slave who was bought by Alp-Tegin, the commander of the royal guard of the Samanid dynasty. Alp-Tegin established himself as the governor of Ghazna in 962, and died a year later in 963.', 942, 997, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-sabuktigin-942-ghaznavid', 'Wikipedia: Sabuktigin', 'digital', 'English Wikipedia, "Sabuktigin", en.wikipedia.org/wiki/Sabuktigin (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Sabuktigin', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-sabuktigin-942-ghaznavid', 'Name, dates and summary.', 'sabuktigin-942-ghaznavid');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('muhammad-quli-qutb-shah-1565-golconda', 'muhammad-quli-qutb-shah-1565-golconda', 'Muhammad Quli Qutb Shah', 'Sultan of Golconda from 1580 to 1612', 'golconda', 'life'::public.person_date_type, 'Muhammad Quli Qutb Shah (4 April 1565 – 11 January 1612) was the fifth sultan of the Sultanate of Golconda and founder of the city of Hyderabad. He built its architectural centrepiece, the Charminar. He was an able administrator and his reign is considered one of the high points of the Qutb Shahi dynasty. He ascended to the throne in 1580 at the age of 15 and ruled for 31 years.', 1565, 1612, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-muhammad-quli-qutb-shah-1565-golconda', 'Wikipedia: Muhammad Quli Qutb Shah', 'digital', 'English Wikipedia, "Muhammad Quli Qutb Shah", en.wikipedia.org/wiki/Muhammad_Quli_Qutb_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Muhammad_Quli_Qutb_Shah', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-muhammad-quli-qutb-shah-1565-golconda', 'Name, dates and summary.', 'muhammad-quli-qutb-shah-1565-golconda');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('sultan-muhammad-qutb-shah-1582-golconda', 'sultan-muhammad-qutb-shah-1582-golconda', 'Sultan Muhammad Qutb Shah', 'Sultan of Golconda from 1612 to 1626', 'golconda', 'life'::public.person_date_type, 'Sultan Muhammad Qutb Shah (April 1593 – 9 February 1626) was the sixth ruler of the kingdom of Golconda in southern India under the Qutb Shahi dynasty.', 1582, 1625, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-sultan-muhammad-qutb-shah-1582-golconda', 'Wikipedia: Sultan Muhammad Qutb Shah', 'digital', 'English Wikipedia, "Sultan Muhammad Qutb Shah", en.wikipedia.org/wiki/Sultan_Muhammad_Qutb_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Sultan_Muhammad_Qutb_Shah', 'CC BY-SA 4.0');
