INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('quli-qutb-shah-1485-golconda', 'quli-qutb-shah-1485-golconda', 'Quli Qutb Shah', 'Sultan of Golconda from 1518 to 1543', 'golconda', 'life'::public.person_date_type, 'Sultan Quli Qutb-ul-Mulk, more often though less correctly referred to in English as Quli Qutb Shah (1485 – 2 September 1543), was the founder of the Qutb Shahi dynasty, which ruled the Sultanate of Golconda in southern India from 1518 to 1687.', 1485, 1543, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-quli-qutb-shah-1485-golconda', 'Wikipedia: Quli Qutb Shah', 'digital', 'English Wikipedia, "Quli Qutb Shah", en.wikipedia.org/wiki/Quli_Qutb_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Quli_Qutb_Shah', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-quli-qutb-shah-1485-golconda', 'Name, dates and summary.', 'quli-qutb-shah-1485-golconda');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('subhan-quli-qutb-shah-1543-golconda', 'subhan-quli-qutb-shah-1543-golconda', 'Subhan Quli Qutb Shah', 'Sultan of Golconda in 1550', 'golconda', 'life'::public.person_date_type, 'Subhan Quli Qutb Shah (1543–1550) was 7 years old, when he became Sultan of Golconda, after the death of his father Jamsheed Quli Qutb Shah, in 1550. Saif Khan, also known as Ainul Mulk, was sent from Ahmednagar for the performance of duties of regent during the boy''s development. But Jamsheed''s younger brother Ibrahim Quli Qutb Shah returned from Vijayanagara to Golconda, and ascended the throne.', 1543, 1550, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-subhan-quli-qutb-shah-1543-golconda', 'Wikipedia: Subhan Quli Qutb Shah', 'digital', 'English Wikipedia, "Subhan Quli Qutb Shah", en.wikipedia.org/wiki/Subhan_Quli_Qutb_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Subhan_Quli_Qutb_Shah', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-subhan-quli-qutb-shah-1543-golconda', 'Name, dates and summary.', 'subhan-quli-qutb-shah-1543-golconda');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('nara-bhupal-shah-1697-gorkha', 'nara-bhupal-shah-1697-gorkha', 'Nara Bhupal Shah', 'King of Gorkha Kingdom from 1716 to 1743', 'gorkha', 'life'::public.person_date_type, 'Nara Bhupal Shah was a king of the Gorkha Kingdom, which lies in modern day Nepal; and the father of Prithvi Narayan Shah. Nara Bhupal Shah was the son of Birbhadra Shah, the grandson of Prithvipati Shah. He was the king of the Gorkha state in Nepal. He unsuccessfully tried to extend his kingdom by capturing Nuwakot.', 1697, 1743, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-nara-bhupal-shah-1697-gorkha', 'Wikipedia: Nara Bhupal Shah', 'digital', 'English Wikipedia, "Nara Bhupal Shah", en.wikipedia.org/wiki/Nara_Bhupal_Shah (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Nara_Bhupal_Shah', 'CC BY-SA 4.0');
