INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('veera-ballala-i-1102-hoysala', 'veera-ballala-i-1102-hoysala', 'Veera Ballala I', 'Hoysala King from 1102 to 1108', 'hoysala', 'time_as_ruler'::public.person_date_type, 'Veera Ballala I (r. 1102–1108) succeeded Ereyanga as king of the Hoysala Empire. He was a Jain by faith. His rule was short and uneventful other than subduing the Chengalvas and the Santharas. He made some unsuccessful attempts to end the overlordship of the Western Chalukyas but was brought under control by Chalukya Vikramaditya VI.', 1102, 1108, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-veera-ballala-i-1102-hoysala', 'Wikipedia: Veera Ballala I', 'digital', 'English Wikipedia, "Veera Ballala I", en.wikipedia.org/wiki/Veera_Ballala_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Veera_Ballala_I', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-veera-ballala-i-1102-hoysala', 'Name, dates and summary.', 'veera-ballala-i-1102-hoysala');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ereyanga-1098-hoysala', 'ereyanga-1098-hoysala', 'Ereyanga', 'Hoysala King from 1098 to 1102 CE', 'hoysala', 'time_as_ruler'::public.person_date_type, 'Ereyanga (r. 1098–1102 CE) was the son of Vinayaditya and distinguished himself as a Chalukya feudatory during their campaigns against Dhara of Malwa. Though he remained the Yuvaraja or crown prince for several decades, his rule as a monarch of Hoysala Empire was short. He was a Jain by faith and took the title ''Vira Ganga''.', 1098, 1102, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-ereyanga-1098-hoysala', 'Wikipedia: Ereyanga', 'digital', 'English Wikipedia, "Ereyanga", en.wikipedia.org/wiki/Ereyanga (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Ereyanga', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-ereyanga-1098-hoysala', 'Name, dates and summary.', 'ereyanga-1098-hoysala');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('nripa-kama-ii-1026-hoysala', 'nripa-kama-ii-1026-hoysala', 'Nripa Kama II', 'Hoysala King from 1026 to 1047 CE', 'hoysala', 'time_as_ruler'::public.person_date_type, 'Nripa Kama II (r. 1026–1047 CE) was an early king of the Hoysala Empire from the Malnad region of Karnataka and was possibly a vassal of the Western Ganga Dynasty and fought many wars against the Cholas. Though unable to rout the Cholas from southern regions of present-day Karnataka, he successfully ruled some regions in the Malnad area.', 1026, 1047, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-nripa-kama-ii-1026-hoysala', 'Wikipedia: Nripa Kama II', 'digital', 'English Wikipedia, "Nripa Kama II", en.wikipedia.org/wiki/Nripa_Kama_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Nripa_Kama_II', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-nripa-kama-ii-1026-hoysala', 'Name, dates and summary.', 'nripa-kama-ii-1026-hoysala');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('veera-ramanatha-1263-hoysala', 'veera-ramanatha-1263-hoysala', 'Veera Ramanatha', 'King of the Hoysala Empire', 'hoysala', 'time_as_ruler'::public.person_date_type, 'Vira Ramanatha (1263–1297 CE) was a king of the southern portion of the Hoysala Empire. In 1254 CE, Hoysala king Vira Someshwara divided his kingdom between his two sons, Narasimha III (reign c. 1263–1292 CE) who ruled from Halebidu (Dorasamudra or Dwarasamudra), their original capital, had got the greater part of the ancestral kingdom and Vira Ramanatha Deva (reign c.', 1263, 1292, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-veera-ramanatha-1263-hoysala', 'Wikipedia: Veera Ramanatha', 'digital', 'English Wikipedia, "Veera Ramanatha", en.wikipedia.org/wiki/Veera_Ramanatha (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Veera_Ramanatha', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-veera-ramanatha-1263-hoysala', 'Name, dates and summary.', 'veera-ramanatha-1263-hoysala');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('veera-ballala-iv-1343-hoysala', 'veera-ballala-iv-1343-hoysala', 'Veera Ballala IV', 'Hoysala king from 1343 to 1346', 'hoysala', 'time_as_ruler'::public.person_date_type, 'Veera Ballala IV was the last Hoysala king from 1343 until his death in 1346. He was the eldest son and successor of the powerful Hoysala emperor Veera Ballala III. He resided over a declining Hoysala kingdom, and was in constant war with the Turko-Persian Madurai Sultanate and an upcoming Vijayanagara Empire.', 1343, 1346, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-veera-ballala-iv-1343-hoysala', 'Wikipedia: Veera Ballala IV', 'digital', 'English Wikipedia, "Veera Ballala IV", en.wikipedia.org/wiki/Veera_Ballala_IV (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Veera_Ballala_IV', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-veera-ballala-iv-1343-hoysala', 'Name, dates and summary.', 'veera-ballala-iv-1343-hoysala');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('vinayaditya-1047-hoysala', 'vinayaditya-1047-hoysala', 'Vinayaditya', 'Hoysala King from 1047 to 1098 CE', 'hoysala', 'time_as_ruler'::public.person_date_type, 'Vinayaditya (r. 1047 – 1098 CE) was an able Jain king of the Hoysala Empire, who distinguished himself as an able feudatory of the Kalyani Chalukyas during his long reign. He helped bring many small Malnad chiefs like the Kongalvas, Chengalvas, Santharas of Humcha Shimoga and the Kadambas of Bayalnadu (Vainadu) under control.', 1047, 1098, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-vinayaditya-1047-hoysala', 'Wikipedia: Vinayaditya (Hoysala dynasty)', 'digital', 'English Wikipedia, "Vinayaditya (Hoysala dynasty)", en.wikipedia.org/wiki/Vinayaditya_(Hoysala_dynasty) (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Vinayaditya_(Hoysala_dynasty)', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-vinayaditya-1047-hoysala', 'Name, dates and summary.', 'vinayaditya-1047-hoysala');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('sthitavarman-600-kamarupa', 'sthitavarman-600-kamarupa', 'Sthitavarman', 'King of Kamarupa', 'kamarupa', 'time_as_ruler'::public.person_date_type, 'Sthitavarman ruled Kamarupa from the Varman dynasty for the period 566–590, was son of Kamarupi King Chandramukhavarman and Queen Bhogavati.', 600, 615, 'about', 'about', 'likely');
