INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('susthitavarman-590-kamarupa', 'susthitavarman-590-kamarupa', 'Susthitavarman', 'King of Kamarupa', 'kamarupa', 'life'::public.person_date_type, 'Susthitavarman (also known as Sri-Mriganka) (590-595) was a ruler of Kamarupa. He was a son of Sthitavarman and Queen Nayanadevi.', 590, 595, 'about', 'about', 'likely');
