INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('lohar-khan-1579-kashmir-sultanate', 'lohar-khan-1579-kashmir-sultanate', 'Lohar Khan', 'Sultan of Kashmir from 1579 to 1580', 'kashmir-sultanate', 'time_as_ruler'::public.person_date_type, 'Lohar Khan Chak was the 24th Sultan of Kashmir. He, with the help of his Wazīr Abdal Bhat, toppled the government of his predecessor Sayyid Mubarak and ascended the throne in November 1579 thus restoring and becoming the fifth ruler of the Chak dynasty.', 1579, 1580, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-lohar-khan-1579-kashmir-sultanate', 'Wikipedia: Lohar Khan', 'digital', 'English Wikipedia, "Lohar Khan", en.wikipedia.org/wiki/Lohar_Khan (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Lohar_Khan', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-lohar-khan-1579-kashmir-sultanate', 'Name, dates and summary.', 'lohar-khan-1579-kashmir-sultanate');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('sayyid-mubarak-1579-kashmir-sultanate', 'sayyid-mubarak-1579-kashmir-sultanate', 'Sayyid Mubarak', 'Sultan of Kashmir in 1579', 'kashmir-sultanate', 'time_as_ruler'::public.person_date_type, 'Sayyid Mubarak Baihaqi was the 23rd Sultan of Kashmir who ascended the throne in February 1579, replacing Yousuf Shah Chak. He was dethroned in November 1579 by Lohar Khan Chak, restoring the Chak dynasty in the monarchy of Kashmir. He also served Ali Shah Chak as his Wazīr which was, after the Sultan, the highest civil office in the Kashmiri government.', 1579, 1579, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-sayyid-mubarak-1579-kashmir-sultanate', 'Wikipedia: Sayyid Mubarak', 'digital', 'English Wikipedia, "Sayyid Mubarak", en.wikipedia.org/wiki/Sayyid_Mubarak (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Sayyid_Mubarak', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-sayyid-mubarak-1579-kashmir-sultanate', 'Name, dates and summary.', 'sayyid-mubarak-1579-kashmir-sultanate');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('yakub-shah-chak-1586-kashmir-sultanate', 'yakub-shah-chak-1586-kashmir-sultanate', 'Yakub Shah Chak', 'Sultan of Kashmir from 1586 to 1589', 'kashmir-sultanate', 'time_as_ruler'::public.person_date_type, 'Ya''qūb (Yākūb) Shāh Chak was the sixth and the last Chak Sultan of Kashmir Sultanate, who reigned from 1586 to 1589. Yakub succeeded his father Yousuf Shah Chak, under warlike conditions, after Kashmir was invaded by the Mughal forces in late 1585.', 1586, 1589, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-yakub-shah-chak-1586-kashmir-sultanate', 'Wikipedia: Yakub Shah Chak', 'digital', 'English Wikipedia, "Yakub Shah Chak", en.wikipedia.org/wiki/Yakub_Shah_Chak (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Yakub_Shah_Chak', 'CC BY-SA 4.0');
