INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('zayn-al-abidin-the-great-1401-kashmir-sultanate', 'zayn-al-abidin-the-great-1401-kashmir-sultanate', 'Zayn al-Abidin the Great', 'Sultan of Kashmir (r. 1418–1419, 1420–1470)', 'kashmir-sultanate', 'life'::public.person_date_type, 'Qutb al-Din Zayn al-Abidin, more famously known as Zayn al-Abidin the Great, was the ninth sultan of the Kashmir Sultanate. He was given the mandate to rule in 1418 in the absence of his brother, Ali Shah before defeating him in the ensuing civil war in 1420 with the help of Jasrat Khokhar. After his illness and subsequent death, his son Haider Shah succeeded him in 1470. He is remembered as Buḍshāh (lit.', 1401, 1470, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-zayn-al-abidin-the-great-1401-kashmir-sultanate', 'Wikipedia: Zayn al-Abidin the Great', 'digital', 'English Wikipedia, "Zayn al-Abidin the Great", en.wikipedia.org/wiki/Zayn_al-Abidin_the_Great (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Zayn_al-Abidin_the_Great', 'CC BY-SA 4.0');
