INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('harsha-of-kashmir-1089-lohara', 'harsha-of-kashmir-1089-lohara', 'Harsha of Kashmir', 'Maharaja of Kashmir from 1089 to 1101', 'lohara', 'time_as_ruler'::public.person_date_type, 'Harsha (1059 – 31 August 1101), also known as Harshadeva, was the Maharaja of Kashmir from 1089 to 1101. He was given the epithet "raja-Turushka" (Turk king).', 1089, 1101, 'about', 'about', 'likely');
