INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('alagiri-nayak-1675-madurai-nayaks', 'alagiri-nayak-1675-madurai-nayaks', 'Alagiri Nayak', 'Ruler of Madurai Nayaks', 'madurai-nayaks', 'time_as_ruler'::public.person_date_type, 'Alagiri Nayak was the younger brother of the Madurai Nayak king Chokkanatha Nayak and the last Nayak king of Thanjavur. In 1675, Thanjavur was conquered by Ekoji I, the half-brother of Shivaji who founded the Thanjavur Maratha kingdom.', 1675, 1690, 'about', 'about', 'likely');
