INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ariyanatha-mudaliar-1529-madurai-nayaks', 'ariyanatha-mudaliar-1529-madurai-nayaks', 'Ariyanatha Mudaliar', 'Ruler of Madurai Nayaks', 'madurai-nayaks', 'time_as_ruler'::public.person_date_type, 'Ariyanatha Mudaliar was the Delavoy (General) and the Chief Minister of the greatest of the Nayaka domains established by the Vijayanagar viceroy and later ruler of Madurai, Viswanatha Nayak (1529–64).', 1529, 1569, 'about', 'about', 'likely');
