INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('bangaru-thirumala-nayaka-1704-madurai-nayaks', 'bangaru-thirumala-nayaka-1704-madurai-nayaks', 'Bangaru Thirumala Nayaka', 'Ruler of Madurai Nayaks', 'madurai-nayaks', 'life'::public.person_date_type, 'Bangaru Thirumala Nayaka, also known as Bangaru Tirumala and Vangaru Thirumala (as per European Records and notes), was a member of Madurai Nayak royal family and Governor/Commander of the Madurai Nayak King Vijaya Ranga Chokkanatha (1704–1731). His son, a young boy was adopted and crowned to the Madurai Throne, with the queen Meenakshi as queen regent, when the Madurai king died without heir.', 1704, 1731, 'about', 'about', 'likely');
