INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('chandramathi-mudaliar-1641-madurai-nayaks', 'chandramathi-mudaliar-1641-madurai-nayaks', 'Chandramathi Mudaliar', '17th-century Tamil chieftain', 'madurai-nayaks', 'time_as_ruler'::public.person_date_type, 'Chandramathi Mudaliar was a 17th-century Tamil chieftain and ruler of south Kongu Nadu (Erode region) who fought many battles against the Madurai Nayak', 1641, 1661, 'about', 'about', 'likely');
