INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('chikka-devaraja-1645-mysore', 'chikka-devaraja-1645-mysore', 'Chikka Devaraja', 'Maharaja of Mysore from 1673 to 1704', 'mysore', 'life'::public.person_date_type, 'Chikka Devaraja Wodeyar II (22 September 1645 – 16 November 1704) was the fourteenth maharaja of the Kingdom of Mysore from 1673 to 1704. During this time, Mysore saw further significant expansion after his predecessors. During his rule, centralised military power increased to an unprecedented degree for the region. He also fought battles against maratha king Sambhaji. Aurangzeb made him ally to counter Marathas.', 1645, 1704, 'about', 'about', 'likely');
