INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kanthirava-narasaraja-ii-1673-mysore', 'kanthirava-narasaraja-ii-1673-mysore', 'Kanthirava Narasaraja II', 'Maharaja of Mysore from 1704 to 1714', 'mysore', 'life'::public.person_date_type, 'Kanthirava Narasaraja II (27 December 1672 – March 1714) was the fifteenth maharaja of the Kingdom of Mysore from 1704 to 1714. He was born deaf and came to be called Múk-arasu (literally "mute king"). He succeeded to the throne through the influence of the prime minister, Tirumala Iyengar.', 1673, 1714, 'about', 'about', 'likely');
