INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('gopala-i-750-pala', 'gopala-i-750-pala', 'Gopala I', 'Ruler of Pala', 'pala', 'time_as_ruler'::public.person_date_type, 'Gopala I (r. c. 750–768 CE) was the founder of the Pala dynasty, which was based in the Bengal region of the Indian subcontinent. He rose to power after being elected by a group of regional chieftains and officials.', 750, 768, 'about', 'about', 'likely');
