INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kumarapala-1130-pala', 'kumarapala-1130-pala', 'Kumarapala', 'Pala Emperor', 'pala', 'time_as_ruler'::public.person_date_type, 'Kumarapala was the successor to the Pala king Ramapala in the Bengal region of the Indian subcontinent, and sixteenth ruler of the Pala line reigning for 10 years. During his reign, he put down an uprising in Kamarupa by the governor Timgyadeva, eventually replacing him with Vaidyadeva (who would rebel four years after the death of Kumarapala).', 1130, 1139, 'about', 'about', 'likely');
