INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('madanapala-1139-pala', 'madanapala-1139-pala', 'Madanapala', 'Pala Emperor', 'pala', 'time_as_ruler'::public.person_date_type, 'Madanapala (r. 1139–1161 CE) was the successor to the Pala king Gopala IV in the Bengal region of the Indian subcontinent, and the eighteenth and final ruler of Pala lineage reigning for 18 years. He was succeeded by Govindapala, whose lineage of that name is questionable.', 1139, 1161, 'about', 'about', 'likely');
