INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('mahipala-978-pala', 'mahipala-978-pala', 'Mahipala', 'Pala emperor from 978 to 1026', 'pala', 'time_as_ruler'::public.person_date_type, 'Mahipala (r. 978–1026), also known as Mahipala I, was the Pala emperor from 978 until his death in 1026. He was the son and successor of Vigrahapala II. Mahipala''s reign marked a resurgence in fortunes for the Pala empire, whose boundaries were expanded as far as Varanasi. However, his rule was temporarily hampered by the northern expedition of the Chola Emperor, Rajendra I.', 978, 1026, 'about', 'about', 'likely');
