INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('aparajita-varman-880-pallava', 'aparajita-varman-880-pallava', 'Aparajita Varman', 'Last Pallava emperor (r. 880–897)', 'pallava', 'time_as_ruler'::public.person_date_type, 'Aparajita Varman (reigned 880–897), commonly referred to as Aparajita, was a king of the Pallava dynasty. He was the son of Kampavarman and the Ganga princess Vijaya. Considered the last known Pallava ruler, he was defeated and killed in c. 897 CE in a battle against Aditya I. Pallava rule over Tondaimandalam came to an end thereafter, as the Pallava territories were annexed into the Chola Empire.', 880, 897, 'about', 'about', 'likely');
