INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kalarsinga-nayanar-700-pallava', 'kalarsinga-nayanar-700-pallava', 'Kalarsinga Nayanar', 'Ruler of Pallava', 'pallava', 'time_as_ruler'::public.person_date_type, 'Kalarsinga Nayanar, also known as Kalarsinga, Kazharsinga, Kalarcinkan, Kalarsingan, Kalarsinganar, Kalarsingar, Kalarcingar and Kalar-chingar (Kalar-singar), was a Nayanar saint, venerated in the Hindu sect of Shaivism. He is generally counted as the fifty-fifth in the list of 63 Nayanars.', 700, 728, 'about', 'about', 'likely');
