INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('nandivarman-iii-846-pallava', 'nandivarman-iii-846-pallava', 'Nandivarman III', 'Pallava emperor from 846 to 869', 'pallava', 'time_as_ruler'::public.person_date_type, 'Nandivarman III (r. 846–869) was a monarch of the Nandivarman II line, who ruled the Pallava kingdom from 846 to 869. He was the son of Dantivarman and the grandson of Nandivarman II.', 846, 869, 'about', 'about', 'likely');
