INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('nriputungavarman-869-pallava', 'nriputungavarman-869-pallava', 'Nriputungavarman', 'Pallava King', 'pallava', 'time_as_ruler'::public.person_date_type, 'Nriputungavarman (fl. c. 869–880 CE) was a king of the Pallava dynasty. Nriputungavarman was the younger son of Nandivarman III and his wife, the Rashtrakuta princess Shankha. Nrpatungavarman had at least two queens, Viramahadevi and Kadavanmadevi, as both appear in his inscriptions as donors. Under his reign, a Vishnu temple in Ukkal was commissioned for his queen.', 869, 880, 'about', 'about', 'likely');
