INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kochchadaiyan-ranadhira-670-pandya', 'kochchadaiyan-ranadhira-670-pandya', 'Kochchadaiyan Ranadhira', 'Pandya king', 'pandya', 'time_as_ruler'::public.person_date_type, 'Kochchadaiyan, known as Ranadhira,(r. c. 670 – 710 AD) was a Pandya king of early medieval south India. He was the son and successor of Arikesari Maravarman c. 640–670 CE The name of the king is famously omitted in the Tamil portion of the Larger Sinnamanur Plates.', 670, 710, 'about', 'about', 'likely');
