INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('maravarman-kulasekara-pandyan-i-1268-pandya', 'maravarman-kulasekara-pandyan-i-1268-pandya', 'Maravarman Kulasekara Pandyan I', 'Pandyan emperor from 1268 to 1308', 'pandya', 'life'::public.person_date_type, 'Maravarman Kulasekara Pandyan I was a Pandyan emperor who ruled regions of South India between 1268–1308 CE, though history professor Sailendra Sen states he ruled until 1310. In 1279 CE, Maravarman Kulasekara Pandyan ended the rule of Chola dynasty by defeating Rajendra III of Cholas and Ramanatha of Hoysalas. His death lead to the Pandyan Civil War in 1308–1323.', 1268, 1308, 'about', 'about', 'likely');
