INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('parakrama-pandyan-i-1169-pandya', 'parakrama-pandyan-i-1169-pandya', 'Parakrama Pandyan I', 'Kings of Madurai', 'pandya', 'life'::public.person_date_type, 'Parakrama Pandyan I was a Pandyan king of Tamilakkam, ruling from the Pandyan capital in Madurai. He was besieged in the Pandyan Civil War (1169–1177) by his contemporary, rival and throne claimant Kulasekhara Pandyan in 1169, a vassal of the Chola Dynasty. Parakrama Pandyan I sought assistance from the Ceylonese king Parakramabahu I of Polonnaruwa, but was subsequently executed.', 1169, 1177, 'about', 'about', 'likely');
