INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('sadayavarman-vikkiraman-i-1250-pandya', 'sadayavarman-vikkiraman-i-1250-pandya', 'Sadayavarman Vikkiraman I', 'Pandyan co-emperor from 1241 to 1250', 'pandya', 'time_as_ruler'::public.person_date_type, 'Sadayavarman Vikkiraman I was king and Lord Emperor of the Pandya dynasty, ruling regions of Tamilakkam (present day South India between 1250–1268). Jatavarman Sundara Pandyan I is remembered for his patronage of the arts and architecture, paying attention to the refurbishment and decoration of Kovils in the Tamil continent. He oversaw the massive economic growth of the Pandyan kingdom.', 1250, 1268, 'about', 'about', 'likely');
