INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('varaguna-ii-862-pandya', 'varaguna-ii-862-pandya', 'Varaguna II', 'Pandyan king from 862 to 879', 'pandya', 'time_as_ruler'::public.person_date_type, 'Varagunavarman II, also known as Varaguna II, and Arimardhana, was a king of the Pandya dynasty in south India whose reign lasted from c. 862 until c. 879 CE. Varaguna II was famously defeated by a contingent of troops led by Pallava king Aparajita around 879 CE.', 862, 879, 'about', 'about', 'likely');
