INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('bhoja-ii-of-malwa-1208-paramara', 'bhoja-ii-of-malwa-1208-paramara', 'Bhoja II of Malwa', 'King of Malwa', 'paramara', 'time_as_ruler'::public.person_date_type, 'Bhoja II was a 13th-century king of the Paramara dynasty in central India. He succeeded Arjuna II as the king of Dhara in Malwa region.', 1208, 1228, 'about', 'about', 'likely');
