INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('jagadeva-1141-paramara', 'jagadeva-1141-paramara', 'Jagadeva', 'Ruler of Paramara', 'paramara', 'time_as_ruler'::public.person_date_type, 'Jagadeva, also known as Jagaddeva or Jagdev Parmar, was an 11th-12th century prince from the Paramara dynasty of central India. He is known from an inscription discovered at Jainad and some folk legends. His political status is uncertain, although according to one theory, he may have been a vassal of the Western Chalukyas.', 1141, 1161, 'about', 'about', 'likely');
