INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-jagadeva-1141-paramara', 'Name, dates and summary.', 'jagadeva-1141-paramara');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kalinga-magha-1215-polonnaruwa', 'kalinga-magha-1215-polonnaruwa', 'Kalinga Magha', 'King of Polonnaruwa (1215–1236) and Jaffna (1215–1255)', 'polonnaruwa', 'time_as_ruler'::public.person_date_type, 'Kalinga Magha or Gangaraja Kalinga Vijayabahu was an invader from the Kingdom of Kalinga who usurped the throne from Parakrama Pandyan II of Polonnaruwa in 1215. A massive migration followed of Sinhalese people to the south and west of Sri Lanka, and into the mountainous interior, as they attempted to escape his power.', 1215, 1236, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-kalinga-magha-1215-polonnaruwa', 'Wikipedia: Kalinga Magha', 'digital', 'English Wikipedia, "Kalinga Magha", en.wikipedia.org/wiki/Kalinga_Magha (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Kalinga_Magha', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-kalinga-magha-1215-polonnaruwa', 'Name, dates and summary.', 'kalinga-magha-1215-polonnaruwa');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('queen-lilavati-1153-polonnaruwa', 'queen-lilavati-1153-polonnaruwa', 'Queen Lilavati', '12th- and 13th-century queen of Polonnaruwa', 'polonnaruwa', 'time_as_ruler'::public.person_date_type, 'Lilavati, (also Leelawathi, Leelavathi) reigned as Queen of Polonnaruwa in 1197–1200, 1209–1210, and 1211–1212. She was the fourth woman in Sri Lankan history to rule as sovereign in her own right. Lilavati rose to prominence as the wife of Parakramabahu I, king of the Kingdom of Polonnaruwa.', 1153, 1186, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-queen-lilavati-1153-polonnaruwa', 'Wikipedia: Queen Lilavati', 'digital', 'English Wikipedia, "Queen Lilavati", en.wikipedia.org/wiki/Queen_Lilavati (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Queen_Lilavati', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-queen-lilavati-1153-polonnaruwa', 'Name, dates and summary.', 'queen-lilavati-1153-polonnaruwa');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('nissanka-malla-1157-polonnaruwa', 'nissanka-malla-1157-polonnaruwa', 'Nissanka Malla', 'King of Polonnaruwa from 1187 to 1196', 'polonnaruwa', 'life'::public.person_date_type, 'Nissanka Malla, also known as Kirti Nissanka and Kalinga Lokaswara, was a king of Polonnaruwa (Sri Lanka) who ruled the country from 1187 to 1196. He is known for his architectural constructions such as the Nissanka Lata Mandapaya, Hatadage and Rankot Vihara, as well as for the refurbishment of old temples and irrigation tanks.', 1157, 1196, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-nissanka-malla-1157-polonnaruwa', 'Wikipedia: Nissanka Malla', 'digital', 'English Wikipedia, "Nissanka Malla", en.wikipedia.org/wiki/Nissanka_Malla (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Nissanka_Malla', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-nissanka-malla-1157-polonnaruwa', 'Name, dates and summary.', 'nissanka-malla-1157-polonnaruwa');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('parakrama-pandyan-ii-1212-polonnaruwa', 'parakrama-pandyan-ii-1212-polonnaruwa', 'Parakrama Pandyan II', 'King of Polonnaruwa from 1212 to 1215', 'polonnaruwa', 'time_as_ruler'::public.person_date_type, 'Parakrama Pandyan II, also Pandu Parakramabahu of Polonnaruwa or Parakrama Pandu, was a Pandyan king who invaded the Kingdom of Polonnaruwa in the thirteenth century and ruled from 1212 to 1215 CE. His namesake royal Parakrama Pandyan I had ruled in Madurai fifty years earlier and had sought help from his contemporary Parakramabahu I of Polonnaruwa when faced with a Pandyan civil war.', 1212, 1215, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-parakrama-pandyan-ii-1212-polonnaruwa', 'Wikipedia: Parakrama Pandyan II', 'digital', 'English Wikipedia, "Parakrama Pandyan II", en.wikipedia.org/wiki/Parakrama_Pandyan_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Parakrama_Pandyan_II', 'CC BY-SA 4.0');
