INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('vijayabahu-i-1039-polonnaruwa', 'vijayabahu-i-1039-polonnaruwa', 'Vijayabahu I', 'King of Polonnaruwa from 1055 to 1110', 'polonnaruwa', 'life'::public.person_date_type, 'Vijayabahu I (1039–1110), also known as Vijayabahu the Great, was the Sinhalese king from 1055 to 1110. Vijayabahu reigned as King of Polonnaruwa from 1070 to 1110, and as the King of Anuradhapura-in-exile before that from 1055 to 1070.', 1039, 1110, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-vijayabahu-i-1039-polonnaruwa', 'Wikipedia: Vijayabahu I', 'digital', 'English Wikipedia, "Vijayabahu I", en.wikipedia.org/wiki/Vijayabahu_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Vijayabahu_I', 'CC BY-SA 4.0');
