INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('vira-bahu-i-1179-polonnaruwa', 'vira-bahu-i-1179-polonnaruwa', 'Vira Bahu I', 'King of Polonnaruwa in 1196', 'polonnaruwa', 'life'::public.person_date_type, 'Vira Bahu I (1196) was son of Nissanka Malla and king of the Kingdom of Polonnaruwa, in present-day Sri Lanka. He came to the throne after his father''s death, however only managed to reign for less than a day, being crowned at night and slain at dawn by the commander-in-chief of the army, Tavuru Senevirat on the grounds that he was a son not equal to his father.', 1179, 1196, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-vira-bahu-i-1179-polonnaruwa', 'Wikipedia: Vira Bahu I', 'digital', 'English Wikipedia, "Vira Bahu I", en.wikipedia.org/wiki/Vira_Bahu_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Vira_Bahu_I', 'CC BY-SA 4.0');
