INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('amoghavarsha-800-rashtrakuta', 'amoghavarsha-800-rashtrakuta', 'Amoghavarsha', 'Rashtrakuta Emperor from 814 to 878', 'rashtrakuta', 'life'::public.person_date_type, 'Amoghavarsha Nrupatunga (c. 800–878), also known as Amoghavarsha I, was the Rashtrakuta emperor from 814 until his death in 878. He is considered by many historians to be the greatest emperor of the Rashtrakuta dynasty. His reign of 64 years is one of the longest precisely dated monarchical reigns on record.', 800, 878, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-amoghavarsha-800-rashtrakuta', 'Wikipedia: Amoghavarsha', 'digital', 'English Wikipedia, "Amoghavarsha", en.wikipedia.org/wiki/Amoghavarsha (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Amoghavarsha', 'CC BY-SA 4.0');
