INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('amoghavarsha-ii-929-rashtrakuta', 'amoghavarsha-ii-929-rashtrakuta', 'Amoghavarsha II', 'Rashtrakuta Emperor from 929 to 930', 'rashtrakuta', 'time_as_ruler'::public.person_date_type, 'Amoghavarsha II (r. 929–930) was a Rashtrakuta emperor who succeeded his father Indra III upon the latter''s death. Amoghavarsha was assassinated by his brother, Govinda IV, who became his successor.', 929, 930, 'about', 'about', 'likely');
