INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('govinda-iv-930-rashtrakuta', 'govinda-iv-930-rashtrakuta', 'Govinda IV', 'Rashtrakuta emperor from 930 to 936', 'rashtrakuta', 'time_as_ruler'::public.person_date_type, 'Govinda IV (reigned 930–936) was the Rashtrakuta emperor from 930 to 936. The younger brother of Amoghavarsha II, Govinda IV became the Rashtrakuta emperor in 930 as described in the Kalasa record of Chikmagalur. He was a very unpopular ruler who indulged in licentious acts. Control over Kannauj was lost during his rule. The Chalukyas of Vengi defeated him and much territory was lost.', 930, 936, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-govinda-iv-930-rashtrakuta', 'Wikipedia: Govinda IV', 'digital', 'English Wikipedia, "Govinda IV", en.wikipedia.org/wiki/Govinda_IV (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Govinda_IV', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-govinda-iv-930-rashtrakuta', 'Name, dates and summary.', 'govinda-iv-930-rashtrakuta');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('indra-iv-973-rashtrakuta', 'indra-iv-973-rashtrakuta', 'Indra IV', 'Rashtrakuta emperor from 973 to 982', 'rashtrakuta', 'life'::public.person_date_type, 'Indra IV (died 20 March 982) was the last Rashtrakuta Emperor from 973 until his death. He was a nephew of the feudatory king of Western Ganga Dynasty of Talakad. After Tailapa II captured Manyakheta, the Ganga Maharaja Marasimha II crowned Indra III as emperor in Bankapura and worked hard to keep the dwindling Rashtrakuta Empire intact after the betrayal and invasion of Parmaras of Malwa but in vain.', 973, 982, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-indra-iv-973-rashtrakuta', 'Wikipedia: Indra IV', 'digital', 'English Wikipedia, "Indra IV", en.wikipedia.org/wiki/Indra_IV (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Indra_IV', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-indra-iv-973-rashtrakuta', 'Name, dates and summary.', 'indra-iv-973-rashtrakuta');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('indra-iii-914-rashtrakuta', 'indra-iii-914-rashtrakuta', 'Indra III', 'Rashtrakuta emperor from 914 to 929', 'rashtrakuta', 'life'::public.person_date_type, 'Indra III (died 929) was the Rashtrakuta emperor from 914 until his death in 929. He was the grandson of Krishna II and son of Chedi princess Lakshmi. He ascended the imperial throne after the early demise of his father Jagattunga. He had many titles such as Nithyavarsha, Rattakandarapa, Rajamarathanda and Kirthinarayana. He patronised Kannada Jain poet and commander Sri Vijaya and Sanskrit poet Trivikrama.', 914, 929, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-indra-iii-914-rashtrakuta', 'Wikipedia: Indra III', 'digital', 'English Wikipedia, "Indra III", en.wikipedia.org/wiki/Indra_III (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Indra_III', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-indra-iii-914-rashtrakuta', 'Name, dates and summary.', 'indra-iii-914-rashtrakuta');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('karka-ii-972-rashtrakuta', 'karka-ii-972-rashtrakuta', 'Karka II', 'Rashtrakuta Emperor from 972 to 973', 'rashtrakuta', 'time_as_ruler'::public.person_date_type, 'Karka II (r. 972 – 973 CE) was a Rashtrakuta Emperor who succeeded his uncle Khottiga Amoghavarsha. By this time the once great Rashtrakuta empire was in decline and the weaknesses created by the earlier plunder of Manyakheta by Paramara King Siyaka II exposed the Rashtrakutas to further depredation who did not survive for long.', 972, 973, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-karka-ii-972-rashtrakuta', 'Wikipedia: Karka II', 'digital', 'English Wikipedia, "Karka II", en.wikipedia.org/wiki/Karka_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Karka_II', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-karka-ii-972-rashtrakuta', 'Name, dates and summary.', 'karka-ii-972-rashtrakuta');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('khottiga-967-rashtrakuta', 'khottiga-967-rashtrakuta', 'Khottiga', 'Rashtrakuta Emperor from 967 to 972', 'rashtrakuta', 'time_as_ruler'::public.person_date_type, 'Khottiga or Amoghavarsha IV (r. 967–972 CE), who bore the title Nityavarsha, was a Rashtrakuta Emperor. During his reign, the Rashtrakutas started to decline. The Paramara King Siyaka II plundered Manyakheta and Khottiga died fighting them. This information is available from the Jain work Mahapurana written by Pushpadanta. He was succeeded by Karka II who only reigned for a few months.', 967, 972, 'about', 'about', 'likely');
