INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('krishna-ii-878-rashtrakuta', 'krishna-ii-878-rashtrakuta', 'Krishna II', 'Rashtrakuta emperor from 878 to 914', 'rashtrakuta', 'time_as_ruler'::public.person_date_type, 'Krishna II (r. 878–914 CE), also known as Akālavarṣa, was the Rashtrakuta emperor from 878 to 914. He ascended the Rashtrakuta throne after the demise of his illustrious father Amoghavarsha Nrupatunga. His queen was a Haihaya princess of Chedi called Mahadevi.', 878, 914, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-krishna-ii-878-rashtrakuta', 'Wikipedia: Krishna II', 'digital', 'English Wikipedia, "Krishna II", en.wikipedia.org/wiki/Krishna_II (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Krishna_II', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-krishna-ii-878-rashtrakuta', 'Name, dates and summary.', 'krishna-ii-878-rashtrakuta');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('krishna-iii-939-rashtrakuta', 'krishna-iii-939-rashtrakuta', 'Krishna III', 'Rashtrakuta Emperor from 939 to 967', 'rashtrakuta', 'time_as_ruler'::public.person_date_type, 'Krishna III (r. 939 – 967), was the last great warrior and able Rashtrakuta Emperor. He was a shrewd administrator and skillful military campaigner. He waged many wars to restore the glory of the Rashtrakutas and played an important role in rebuilding the Rashtrakuta empire.', 939, 967, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-krishna-iii-939-rashtrakuta', 'Wikipedia: Krishna III', 'digital', 'English Wikipedia, "Krishna III", en.wikipedia.org/wiki/Krishna_III (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Krishna_III', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-krishna-iii-939-rashtrakuta', 'Name, dates and summary.', 'krishna-iii-939-rashtrakuta');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('rama-raya-1484-vijayanagara', 'rama-raya-1484-vijayanagara', 'Rama Raya', 'Regent of Vijayanagara from 1542 to 1565', 'vijayanagara', 'life'::public.person_date_type, 'Rama Raya (1484 – 23 January 1565) was a statesman of the Vijayanagara Empire, the son-in-law of Emperor Krishna Deva Raya and the progenitor of the Aravidu dynasty of Vijayanagara Empire, the fourth and last dynasty of the empire. As a regent, he was the de facto ruler of the empire from 1542 to 1565, although legally the emperor during this period was Sadasiva Raya, who was merely a puppet ruler.', 1484, 1565, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-rama-raya-1484-vijayanagara', 'Wikipedia: Rama Raya', 'digital', 'English Wikipedia, "Rama Raya", en.wikipedia.org/wiki/Rama_Raya (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Rama_Raya', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-rama-raya-1484-vijayanagara', 'Name, dates and summary.', 'rama-raya-1484-vijayanagara');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('peda-venkata-raya-1632-vijayanagara', 'peda-venkata-raya-1632-vijayanagara', 'Peda Venkata Raya', 'Emperor of Vijayanagara from 1632 to 1642', 'vijayanagara', 'time_as_ruler'::public.person_date_type, 'Venkata III (born Pedda Venkata Raya; reigned 1632 – 10 October 1642) was the grandson of Aliya Rama Raya. Venkata III belonged to a Telugu family. and became the King of the Vijayanagara Empire from 1632 to 1642. His son-in-law Pedda Koneti Nayak was ruler of Penukonda. His brothers-in-law were Damarla Venkatappa Nayaka and Damarla Ayyappa Nayaka, both sons of Damarla Chennapa Nayakadu.', 1632, 1642, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-peda-venkata-raya-1632-vijayanagara', 'Wikipedia: Peda Venkata Raya', 'digital', 'English Wikipedia, "Peda Venkata Raya", en.wikipedia.org/wiki/Peda_Venkata_Raya (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Peda_Venkata_Raya', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-peda-venkata-raya-1632-vijayanagara', 'Name, dates and summary.', 'peda-venkata-raya-1632-vijayanagara');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('veera-vijaya-bukka-raya-1423-vijayanagara', 'veera-vijaya-bukka-raya-1423-vijayanagara', 'Veera Vijaya Bukka Raya', 'Emperor of Vijayanagara from 1423 to 1424', 'vijayanagara', 'time_as_ruler'::public.person_date_type, 'Veera Vijaya Bukka Raya (reigned 1423–1424), also known as Bukka Raya III and Vijaya Raya, was an emperor of the Vijayanagara Empire from the Sangama Dynasty.', 1423, 1424, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-veera-vijaya-bukka-raya-1423-vijayanagara', 'Wikipedia: Veera Vijaya Bukka Raya', 'digital', 'English Wikipedia, "Veera Vijaya Bukka Raya", en.wikipedia.org/wiki/Veera_Vijaya_Bukka_Raya (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Veera_Vijaya_Bukka_Raya', 'CC BY-SA 4.0');
