INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('devanampiya-tissa-600-anuradhapura', 'devanampiya-tissa-600-anuradhapura', 'Devanampiya Tissa', 'King of Anuradhapura from 307 BC to 267 BC', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Tissa, later Devanampiya Tissa, also known as Devanape Tis, was one of the earliest kings of Sri Lanka based at the ancient capital of Anuradhapura. According to the traditional chronology, he ruled from 307 BC to 267 BC, but the modified chronology adopted by modern scholars such as Wilhelm Geiger assigns his reign to 247 BC to 207 BC.', 600, 625, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-devanampiya-tissa-600-anuradhapura', 'Wikipedia: Devanampiya Tissa', 'digital', 'English Wikipedia, "Devanampiya Tissa", en.wikipedia.org/wiki/Devanampiya_Tissa (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Devanampiya_Tissa', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-devanampiya-tissa-600-anuradhapura', 'Name, dates and summary.', 'devanampiya-tissa-600-anuradhapura');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('valagamba-809-anuradhapura', 'valagamba-809-anuradhapura', 'Valagamba', 'King of Anuradhapura', 'anuradhapura', 'time_as_ruler'::public.person_date_type, 'Valagamba, also known (in Pāli) as Vaṭṭagāmiṇi Abhaya and Valagam Abha. Valagamba was a king of the Anuradhapura Kingdom of Sri Lanka. Five months after becoming king, he was overthrown by a rebellion and an invasion from South India, but regained the throne by defeating the invaders fourteen years later. He is also known for the construction of the Abhayagiri Dagaba and Aluthepola Ganekanda Raja Maha Vihara.', 809, 834, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-valagamba-809-anuradhapura', 'Wikipedia: Valagamba', 'digital', 'English Wikipedia, "Valagamba", en.wikipedia.org/wiki/Valagamba (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Valagamba', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-valagamba-809-anuradhapura', 'Name, dates and summary.', 'valagamba-809-anuradhapura');
