INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('karikala-850-chola', 'karikala-850-chola', 'Karikala', 'Historical Chola king who ruled over southern India', 'chola', 'time_as_ruler'::public.person_date_type, 'Karikala (Tamil: கரிகால; [kaːrikɑːl]; Middle Tamil: Karikāḷa Cōḻaṉ, often referred to as Karikala the Great and the Death to sin, was a Tamil Emperor of the Early Cholas of the Chola dynasty who ruled ancient Tamilakam (Modern day South India) from Uraiyur and then Puhar. He is credited with the construction of the flood banks of the river Kaveri and conquest of Tamilakam, Andhra and Sri Lanka.', 850, 875, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-karikala-850-chola', 'Wikipedia: Karikala', 'digital', 'English Wikipedia, "Karikala", en.wikipedia.org/wiki/Karikala (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Karikala', 'CC BY-SA 4.0');
INSERT INTO public.information_sources (source_id, note, person_id) VALUES ('wikipedia-person-karikala-850-chola', 'Name, dates and summary.', 'karikala-850-chola');
INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('killivalavan-911-chola', 'killivalavan-911-chola', 'Killivalavan', 'Ruler of Chola', 'chola', 'time_as_ruler'::public.person_date_type, 'Killivalavan was a Tamil king of the Early Cholas mentioned in Sangam literature, and of a period close to that of Nedunkilli and Nalankilli. The information we have for Killivalavan is from the fragmentary poems of Sangam in the Purananuru.', 911, 936, 'about', 'about', 'likely');
