INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('kochchenganan-973-chola', 'kochchenganan-973-chola', 'Kochchenganan', 'Chola Ruler', 'chola', 'time_as_ruler'::public.person_date_type, 'Kochchenganan (Kōccengaṇān) Kochengat Cholan or Śengaṇān (also spelt Senganan) was a monarch of the Early Cholas described in classical Tamil Sangam literature. Contemporary historical details of his reign derive principally from the anthology Purananuru and the martial poem Kaḷavaḻi Nāṟpatu.', 973, 998, 'about', 'about', 'likely');
