INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('pugal-chola-1218-chola', 'pugal-chola-1218-chola', 'Pugal Chola', 'Ruler of Chola', 'chola', 'time_as_ruler'::public.person_date_type, 'Pugal Chola, also known as Pukal Chola, Pukazhchozha Nayanar, Pugazh, Pukazhcchozhar, Pukal Cholan and Pugal Chola Nayanar, is described as a Chola ruler and was a Nayanar saint, venerated in Shaivism, one of the main sects of Hindu. He is generally counted as the eighth in the list of 63 Nayanars.', 1218, 1243, 'about', 'about', 'likely');
