INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('ayn-al-mulk-multani-1206-delhi-sultanate', 'ayn-al-mulk-multani-1206-delhi-sultanate', 'Ayn al-Mulk Multani', 'General of Delhi Sultanate', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, '‘Ayn al-Mulk Mūltānī was a military commander and official who served the Khalji and Tughluq dynasties of the Delhi Sultanate in present-day India. He served as Alauddin Khalji''s governor of Malwa and Devagiri, and after Alauddin''s death, suppressed a revolt in Gujarat.', 1206, 1231, 'about', 'about', 'likely');
