INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('malik-dinar-1366-delhi-sultanate', 'malik-dinar-1366-delhi-sultanate', 'Malik Dinar', '14th century general of the Delhi Sultanate', 'delhi-sultanate', 'time_as_ruler'::public.person_date_type, 'Malik Dinar was a native Indian slave who served as general in Khalji dynasty of Delhi Sultanate. He served as subordinate officer Malik Kafur and was also a Shihna-yi pil or intendant of elephantry and was sent by Kafur to suppress rebellion in Gujarat. His daughter has been married the third Khalji dynasty sultan, Qutbuddin Mubarak Shah. he was given the title ''Zafar Khan'' (literally chief of victory).', 1366, 1391, 'about', 'about', 'likely');
