INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('harishchandra-pal-750-pala', 'harishchandra-pal-750-pala', 'Harishchandra Pal', 'Ruler of Pala', 'pala', 'time_as_ruler'::public.person_date_type, 'Raja Harish Pala or Harishchandra Pala was a historical monarch, who ruled the ancient city of Sarveshwar or modern-day Savar in the Dhaka District of Bangladesh, during between the 10th to 11th centuries CE. This period coincided with the post-Gupta era, a time marked by regional dynasties and the flourishing of Buddhist culture in Bengal.', 750, 775, 'about', 'about', 'likely');
