INSERT INTO public.people (id, page_name, name, role, kingdom_id, date_kind, summary, start_year, end_year, start_date_type, end_date_type, date_confidence) VALUES ('netunceliyan-i-600-pandya', 'netunceliyan-i-600-pandya', 'Netunceliyan I', 'Pandya ruler from Tamilakam', 'pandya', 'time_as_ruler'::public.person_date_type, 'Netunceliyan, was an early Pandya king. Netunceliyan was known by the title Āriyappaṭai-kaṭanta Neṭuñceḻiyaṉ (he who won a victory against an Aryan army). He is a character in Ilango Adigal''s Cilappatikaram, one of the Five Great Epics in Tamil literature.', 600, 625, 'about', 'about', 'likely');
INSERT INTO public.sources (id, title, source_type, source_details, url, licence) VALUES ('wikipedia-person-netunceliyan-i-600-pandya', 'Wikipedia: Netunceliyan I', 'digital', 'English Wikipedia, "Netunceliyan I", en.wikipedia.org/wiki/Netunceliyan_I (CC BY-SA 4.0). Name and dates, and the opening paragraph lightly trimmed.', 'https://en.wikipedia.org/wiki/Netunceliyan_I', 'CC BY-SA 4.0');
